  const PREFIXES = ['un', 're', 'in', 'im', 'dis', 'pre', 'pro', 'ex', 'de', 'con', 'com', 'non', 'mis', 'over', 'under', 'sub', 'super', 'inter', 'trans', 'anti', 'bio', 'geo', 'tele', 'fore', 'en', 'em', 'be', 'out', 'up'];
