const IC = {};
// 白色变体：用于深蓝头部/主色按钮等深色底场景
const ICW = {};
for (const [k, v] of Object.entries(_ICONS)) {
  IC[k] = _svg('vico', v);
  IC[k + 'Sm'] = _svg('vico-sm', v);
  ICW[k] = _svg('vico', v, '#fff');
  ICW[k + 'Sm'] = _svg('vico-sm', v, '#fff');
}
function ico(name, sm = false) { return _svg(sm ? 'vico-sm' : 'vico', _ICONS[name] || ''); }

const POS_RE = /\s*(n|v|vt|vi|adj|adv|prep|conj|pron|art|int|aux|modal|num)\./i;

function formatPhonetic(p) {
  if (!p) return '';
  let s = p.trim();
  // 去掉末尾可能残留的 n./v./adj. 等词性标记
  s = s.replace(/\s+(n|v|vt|vi|adj|adv|prep|conj|pron|art|int|aux|modal|num)\.?$/i, '');
  // 去掉两侧空格
  s = s.trim();
  if (!s) return '';
  // 如果已经有 /.../ 则保持
  if (/^\/.*\/$/.test(s)) return s;
  return '/' + s + '/';
}

// 取单词的「常用译文」：取第一个义项（去掉词性标签与多余义项），用于英译中选项/干扰项。
// 例如 "n. 建立；设立；创办" → "建立"；"v. & n. 影响" → "影响"。
function commonMeaning(raw) {
  if (!raw) return '';
  const norm = normalizeMeaning(raw);
  if (!norm) return '';
  const tokens = norm.split(new RegExp('(?<![A-Za-z])(?=\\s*' + POS_CLASS + ')', 'i'));
  for (const token of tokens) {
    const t = token.trim();
    if (!t) continue;
    // 去掉开头的词性标签（n. v. 等），取其后第一个义项作为常用译文
    const body = t.replace(new RegExp('^\\s*' + POS_CLASS + '\\s*', 'i'), '').trim();
    const senses = body.split(/[；;]/).map((x) => x.trim()).filter((s) => s && /[A-Za-z\u4e00-\u9fa5]/.test(s));
    if (senses.length) return senses[0];
  }
  return '';
}

// 生成英译中选项：以「常用译文」为单位，去重、含正确答案、洗牌，返回字符串数组。
// answerMeaning: 正确单词的 meaning；poolWords: 候选单词对象数组（含 .meaning）。
function buildEn2ZhOptions(answerMeaning, poolWords, n = 10) {
  const ans = commonMeaning(answerMeaning) || answerMeaning;
  const seen = new Set([ans]);
  const dist = [];
  for (const w of shuffle(poolWords)) {
    if (dist.length >= n - 1) break;
    const m = commonMeaning(w.meaning);
    if (!m || seen.has(m)) continue;
    seen.add(m); dist.push(m);
  }
  const opts = shuffle([ans, ...dist]);
  return opts.slice(0, Math.max(2, n));
}

const POS_CLASS = '(?:(?:n|v|vt|vi|adj|adv|prep|conj|pron|art|int|aux|modal|num)\\.)';
// 预处理：消除重复词性标签（n. n. → n.）、把 & 连接的词性规范为可读形式
function normalizeMeaning(raw) {
  if (!raw) return '';
  let s = raw;
  // 去掉「相同词性」的重复标记：n. n. → n.
  s = s.replace(new RegExp('\\b(' + POS_CLASS + ')\\s*(?=\\1)', 'gi'), '');
  // 词性之间用 & 连接（有无空格）：v. & n. / vt.&vi. → v./n. / vt./vi.
  s = s.replace(new RegExp('\\.' + '\\s*&\\s*(?=' + POS_CLASS + ')', 'gi'), './');
  s = s.replace(new RegExp('\\.' + '\\s*&\\s*(?=' + POS_CLASS + ')', 'gi'), './');
  // 孤立的 &（如 v. & 结尾）
  s = s.replace(/\b&\b/g, '');
  s = s.replace(/\.{2,}/g, '.');
  s = s.replace(/\s+/g, ' ').trim();
  return s;
}

function formatMeaningHTML(meaning, maxSense = 3) {
  if (!meaning) return '';
  const norm = normalizeMeaning(meaning);
  if (!norm) return '';
  const tokens = norm.split(new RegExp('(?<![A-Za-z])(?=\\s*' + POS_CLASS + ')', 'i'));
  const lines = [];
  for (const token of tokens) {
    const t = token.trim();
    if (!t) continue;
    const m = t.match(new RegExp('^\\s*(' + POS_CLASS + ')\\s*(.*)$', 'i'));
    if (m) {
      const pos = m[1].toLowerCase();
      let senses = m[2].split(/[；;]/).map((x) => x.trim()).filter(Boolean);
      if (!senses.length) continue; // 词性后无释义则不输出孤立行
      if (senses.length > maxSense) senses = senses.slice(0, maxSense);
      lines.push(`<div class="meaning-line"><b>${pos}</b> ${escapeHtml(senses.join('；'))}</div>`);
    } else {
      let senses = t.split(/[；;]/).map((x) => x.trim()).filter(Boolean);
      if (!senses.length) continue;
      if (senses.length > maxSense) senses = senses.slice(0, maxSense);
      lines.push(`<div class="meaning-line">${escapeHtml(senses.join('；'))}</div>`);
    }
  }
  if (!lines.length) return '';
  return `<div class="meaning-lines">${lines.join('')}</div>`;
}

const FORM_LABELS = { past: '过去式', pp: '过去分词', ing: '现在分词', plural: '复数' };
const FORM_ORDER = ['past', 'pp', 'ing', 'plural'];

function inflectHTML(inflect) {
  const items = FORM_ORDER.filter((k) => inflect[k]).map((k) => {
    const forms = String(inflect[k]).split('/').map((s) => s.trim()).filter(Boolean);
    return forms.map((f) => `<span class="form-chip" data-form="${escapeHtml(f.toLowerCase())}" title="点击查看 ${escapeHtml(f)} 的原形">${FORM_LABELS[k]}<b>${escapeHtml(f)}</b></span>`).join('');
  }).join('');
  if (!items) return '';
  return `<div class="inflect"><div class="inflect-title">词形变化</div><div class="form-chips">${items}</div></div>`;
}

function collocHTML(collocations) {
  if (!collocations || !collocations.length) return '';
  const items = collocations.slice(0, 6).map((c) =>
    `<div class="colloc-item"><b>${escapeHtml(c.phrase)}</b><span>${escapeHtml(c.meaning)}</span></div>`).join('');
  return `<div class="colloc"><div class="colloc-title">常用搭配</div>${items}</div>`;
}

function wordCardHTML(w, { showAudio = true, showNote = true, showStar = true } = {}) {
  if (!w) return '';
  const uk = formatPhonetic(w.phoneticUk || w.phonetic || '');
  const us = formatPhonetic(w.phoneticUs || '');
  // 自然拼读：优先用已存字段；纯单词若缺失则实时用 PhonicsCore 重算（保证重读音节大写）
  let ph = w.phonics || '';
  if (!ph && typeof window !== 'undefined' && window.PhonicsCore && /^[A-Za-z]+$/.test(w.word || '')) {
    ph = window.PhonicsCore.render(w.word);
  }
  const mastered = (window.APP && window.APP.progress && window.APP.progress.mastered && window.APP.progress.mastered[w.word.toLowerCase()]) ? '<span class="pill">已掌握</span>' : '';
  const formNote = w._form ? `<span class="form-note">（${escapeHtml(w._form.base)} 的${FORM_LABELS[w._form.type] || '形式'}）</span>` : '';
  const ukPart = (showAudio && uk) ? `<span class="phon-tag">英</span><span class="audio-btn mini" data-act="uk" data-word="${escapeHtml(w.word)}" title="英音">${IC.volumeSm}</span><span class="phon-uk">${uk}</span>` : (uk ? `<span class="phon-tag">英</span><span class="phon-uk">${uk}</span>` : '');
  const usPart = (showAudio && us) ? `<span class="phon-tag us">美</span><span class="audio-btn mini" data-act="us" data-word="${escapeHtml(w.word)}" title="美音">${IC.volumeSm}</span><span class="phon-us">${us}</span>` : (us ? `<span class="phon-tag us">美</span><span class="phon-us">${us}</span>` : '');
  const phonLine = (uk || us) ? `<div class="word-phon cols">${ukPart}${usPart}</div>` : '';
  const noteBtn = showNote ? `<button class="btn sm gray" data-act="note" data-word="${escapeHtml(w.word)}">+生词本</button>` : '';
  // vxiaozhi 精确助记图：有图才显示。外层 .word-pict-wrap 用 aspect-ratio 裁掉底部约 7.5%
  // （源图右下角固定带「小智晖的AI单词本」水印，位于底边 93.9%~98.1%，裁掉整条底边即彻底去除水印）。
  // 加载失败时整块移除，加载中/无图不占位。
  const pictUrl = (typeof vxImgURL === 'function') ? vxImgURL(w.word) : null;
  const pictHTML = pictUrl
    ? `<div class="word-pict-wrap"><img class="word-pict" src="${escapeHtml(pictUrl)}" alt="${escapeHtml(w.word)} 助记图" loading="lazy" decoding="async" referrerpolicy="no-referrer" onerror="(this.closest('.word-pict-wrap')||this).remove()"></div>`
    : '';
  return `
  <div class="word-card" data-word="${escapeHtml(w.word)}">
    <div class="word-top">
      <div class="word-main">${escapeHtml(w.word)} ${mastered} ${formNote}</div>
    </div>
    ${pictHTML}
    ${phonLine}
    ${ph ? `<div class="phonics">拼读: ${escapeHtml(ph)}</div>` : ''}
    <div class="meaning">${formatMeaningHTML(w.meaning)}</div>
    ${w.inflect ? inflectHTML(w.inflect) : ''}
    ${w.collocations ? collocHTML(w.collocations) : ''}
    ${w.example ? `<div class="example">${escapeHtml(w.example)}<div class="cn">${escapeHtml(w.exampleCn || '')}</div></div>` : ''}
    ${showNote ? `<div class="row mt between"><span class="muted">${w.category ? '分类: ' + escapeHtml(w.category) : ''}</span>${noteBtn}</div>` : ''}
  </div>`;
}

// 绑定单词卡片内的事件（发音/收藏/词形点击）
function bindWordCardEvents(container, c) {
  container.querySelectorAll('[data-act="uk"]').forEach((b) => b.addEventListener('click', () => c.playUK(b.dataset.word)));
  container.querySelectorAll('[data-act="us"]').forEach((b) => b.addEventListener('click', () => c.playUS(b.dataset.word)));
  container.querySelectorAll('[data-act="note"]').forEach((b) => b.addEventListener('click', () => c.toggleNotebook(b.dataset.word)));
  container.querySelectorAll('.form-chip').forEach((b) => b.addEventListener('click', (e) => {
    e.stopPropagation();
    if (c.showWordCard) c.showWordCard(b.dataset.form);
  }));
}

// 随机选项生成（用于英译中/完形）
function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function pickDistractors(allWords, correctWord, field, n) {
  const pool = shuffle(allWords.filter((w) => w.word !== correctWord && (w[field] || '').trim()));
  return pool.slice(0, n).map((w) => w[field]);
}

// 规则复数 → 单数候选数组（仅作候选，是否采用由调用方校验词库存在性决定）
// 覆盖 -ies / -ves / -ches -shes -ses -xes -zes / -es / -s（排除 -ss 等），
// 并补齐双写辅音（quizzes → quizz → quiz）。
function lemmatizePlural(w) {
  if (!w || w.length < 3) return [];
  const s = w.toLowerCase();
  const out = [];
  if (s.endsWith('ies') && s.length > 4) out.push(s.slice(0, -3) + 'y');
  if (s.endsWith('ves') && s.length > 3) out.push(s.slice(0, -3) + 'f'); // wolves→wolf, knives→knife
  if (s.endsWith('ches') || s.endsWith('shes') || s.endsWith('ses') || s.endsWith('xes') || s.endsWith('zes')) out.push(s.slice(0, -2));
  if (s.endsWith('es') && s.length > 3) out.push(s.slice(0, -2));
  if (s.endsWith('s') && !s.endsWith('ss') && s.length > 2) out.push(s.slice(0, -1));
  // 去重 + 双写辅音再退一级（quizzes→quizz→quiz, addresses→addres→address）
  const seen = new Set();
  const res = [];
  for (const c of out) {
    if (!seen.has(c)) { seen.add(c); res.push(c); }
    if (c.length > 3 && c[c.length - 1] === c[c.length - 2]) {
      const d = c.slice(0, -1);
      if (!seen.has(d)) { seen.add(d); res.push(d); }
    }
  }
  return res;
}

// 词库中未收录时，弹出引导跳转网易有道查询的卡片（需求6）
function wordCardNotFoundHTML(word) {
  const w = escapeHtml(word);
  const url = 'https://www.youdao.com/result?word=' + encodeURIComponent(word) + '&lang=en';
  return `
  <div class="word-card notfound">
    <div class="word-main">${w}</div>
    <div class="meaning"><div class="meaning-line">词库中未收录该词</div></div>
    <a class="btn block youdao-link" href="${url}" target="_blank" rel="noopener">${IC.eyeSm}在网易有道查询 “${w}”</a>
    <div class="muted" style="margin-top:8px;font-size:12px">点击将在新标签页打开有道词典结果</div>
  </div>`;
}


/**
 * 复习算法调度器（生词本 / 错词本专用）
 * 三套算法，由设置 reviewAlgo 切换：
 *  - wrong3      三次错误移除：全量推荐错词本与生词本，三项练习连续 3 轮全对 → 判定掌握
 *                （轮次跟踪在 app.js 的 wrongRound / nbRound，本模块只管 eb/fsrs）
 *  - ebbinghaus  艾宾浩斯 6 轮记忆法：6 个固定间隔（1天→2天→4天→7天→15天→30天），
 *                每完成一轮且全对自动进入下一轮复习任务，6 轮全部完成 → 判定掌握
 *  - fsrs        FSRS AI 间隔记忆法（FSRS-4.5 官方 17 参数）：根据记忆表现动态计算
 *                下次复习时间，记忆强度（间隔）≥ 21 天 → 判定掌握毕业
 *
 * 调度状态存于 progress.sched[word]（仅 eb/fsrs 使用），切换算法时自动重建。
 */

/* ---------- 算法元信息（设置界面展示） ---------- */
const ALGOS = {
  wrong3: {
    name: '3 次错误移除算法',
    desc: '全量推荐错词本与生词本；三项练习（中译英/英译中/完形）连续 3 轮全对即判定掌握，中途答错重新计数。',
  },
  ebbinghaus: {
    name: '艾宾浩斯 6 轮记忆法',
    desc: '按遗忘曲线安排 6 轮固定间隔复习（按天）：1天 → 2天 → 4天 → 7天 → 15天 → 30天。每完成一轮且全对自动进入下一轮复习任务，6 轮全部完成判定掌握。',
  },
  fsrs: {
    name: 'FSRS 最强 AI 间隔记忆法',
    desc: 'FSRS-4.5 开源算法，根据每轮记忆表现动态计算下次复习时间与间隔，记得越牢间隔越长；记忆强度达 21 天即毕业掌握。',
  },
};

function currentAlgo() {
  const s = (typeof window !== 'undefined' && window.APP && window.APP.settings) || {};
  return ALGOS[s.reviewAlgo] ? s.reviewAlgo : 'wrong3';
}

/* ---------- 艾宾浩斯：6 轮固定间隔（完成第 stage 轮后，距下一轮的间隔） ---------- */
const EB_STEPS = [
  { ms: 1 * 24 * 3600 * 1000, label: '1 天' },
  { ms: 2 * 24 * 3600 * 1000, label: '2 天' },
  { ms: 4 * 24 * 3600 * 1000, label: '4 天' },
  { ms: 7 * 24 * 3600 * 1000, label: '7 天' },
  { ms: 15 * 24 * 3600 * 1000, label: '15 天' },
  { ms: 30 * 24 * 3600 * 1000, label: '30 天' },
];
const EB_TOTAL = 6; // 完成 6 轮 → 掌握

/* ---------- FSRS-4.5（开源权重，MIT） ---------- */
const FSRS_W = [0.4872, 1.4003, 3.7145, 13.8206, 5.1618, 1.2298, 0.8975, 0.031, 1.6474, 0.1367, 1.0461, 2.1072, 0.0793, 0.3246, 1.587, 0.2272, 2.8755];
const FSRS_DECAY = -0.5;          // 幂衰减指数
const FSRS_FACTOR = 19 / 81;      // 衰减因子
const FSRS_RETENTION = 0.9;       // 目标记忆保留率
const FSRS_GRADUATE = 21;         // 间隔 ≥ 21 天 → 掌握毕业
const FSRS_AGAIN_MIN = 10;        // 忘记后 10 分钟内重学（学习步骤）

const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));

// 可检索概率：距上次复习 elapsed 天后，还记得该词的概率
function retrievability(st, now) {
  const elapsed = Math.max(0, (now - st.last) / 86400000);
  return Math.pow(1 + (FSRS_FACTOR * elapsed) / st.s, FSRS_DECAY);
}
function initStability(g) { return Math.max(0.1, FSRS_W[g - 1]); }
function initDifficulty(g) { return clamp(FSRS_W[4] - (g - 3) * FSRS_W[5], 1, 10); }
function nextDifficulty(d, g) {
  const nd = d - FSRS_W[6] * (g - 3);
  return clamp(FSRS_W[7] * initDifficulty(4) + (1 - FSRS_W[7]) * nd, 1, 10);
}
function nextStability(st, d, g, r) {
  if (g === 1) { // 遗忘：稳定度重置公式
    return FSRS_W[11] * Math.pow(d, -FSRS_W[12]) * (Math.pow(st.s + 1, FSRS_W[13]) - 1) * Math.exp(FSRS_W[14] * (1 - r));
  }
  const hardPenalty = g === 2 ? FSRS_W[15] : 1;
  const easyBonus = g === 4 ? FSRS_W[16] : 1;
  return Math.min(
    st.s * (1 + Math.exp(FSRS_W[8]) * (11 - d) * Math.pow(st.s, -FSRS_W[9]) * (Math.exp(FSRS_W[10] * (1 - r)) - 1) * hardPenalty * easyBonus),
    36500
  );
}
function intervalOf(s) {
  // 使保留率恰好为 FSRS_RETENTION 的间隔（天）
  return Math.max(1, Math.round((s / FSRS_FACTOR) * (Math.pow(FSRS_RETENTION, 1 / FSRS_DECAY) - 1)));
}

/* ---------- 调度状态 ---------- */
function progress() { return window.APP.progress; }
function lwOf(word) { return String(word || '').toLowerCase(); }

// 获取（或初始化）单词的调度状态；算法切换后按新算法重建
function ensureSt(word) {
  const p = progress();
  if (!p.sched) p.sched = {};
  const lw = lwOf(word);
  const a = currentAlgo();
  let st = p.sched[lw];
  if (!st || st.a !== a) {
    st = p.sched[lw] = { a, stage: 0, due: 0, rt: {}, clean: true, s: 0, d: 0, itv: 0, last: 0, reps: 0, lapses: 0 };
  }
  return st;
}

function stOf(word) {
  const p = progress();
  const st = (p.sched || {})[lwOf(word)];
  return (st && st.a === currentAlgo()) ? st : null;
}

// 单词下次到期时间（0 = 新词/从未调度 → 立即到期）
function dueTs(word) {
  const st = stOf(word);
  return st ? (st.due || 0) : 0;
}
function isDue(word) { return dueTs(word) <= Date.now(); }

// 答对一题：轮内三项标记；三项凑齐时返回 true（调用方接着调 onRoundDone 推进轮次）
function onTaskOk(word, task) {
  const st = ensureSt(word);
  st.rt[task] = true;
  return ['zh2en', 'en2zh', 'cloze'].every((k) => st.rt[k]);
}
// 答错一题：本轮作废（clean=false），重练本轮
function onWrongAnswer(word) {
  const st = ensureSt(word);
  st.clean = false;
  st.rt = {};
}

// 一轮三项全部完成 → 按算法推进。返回 { mastered, stage?, itv?, resetRound? }
function onRoundDone(word) {
  const st = ensureSt(word);
  const now = Date.now();
  if (st.a === 'ebbinghaus') {
    if (st.clean) st.stage = (st.stage || 0) + 1; // 本轮全对 → 进入下一轮
    st.rt = {};
    const wasClean = st.clean;
    st.clean = true;
    if (st.stage >= EB_TOTAL) return { mastered: true, stage: st.stage };
    // 本轮没全对：留在当前轮，立即重练；全对：按固定间隔进入下一轮
    st.due = wasClean ? now + EB_STEPS[Math.min(st.stage - 1, EB_STEPS.length - 1)].ms : now;
    return { mastered: false, stage: st.stage };
  }
  // FSRS：一轮全对=Good(3)；轮内有错=Again(1)
  const rating = st.clean ? 3 : 1;
  const r = st.reps > 0 ? retrievability(st, now) : 1;
  if (st.reps === 0) {
    st.s = initStability(rating);
    st.d = initDifficulty(rating);
  } else {
    st.d = nextDifficulty(st.d, rating);
    st.s = nextStability(st, st.d, rating, r);
  }
  st.last = now;
  st.reps = (st.reps || 0) + 1;
  if (rating === 1) st.lapses = (st.lapses || 0) + 1;
  st.rt = {};
  st.clean = true;
  if (rating === 1) {
    st.itv = 0;
    st.due = now + FSRS_AGAIN_MIN * 60 * 1000; // 忘记 → 10 分钟后重学
    return { mastered: false, itv: 0 };
  }
  const itv = intervalOf(st.s);
  st.itv = itv;
  if (itv >= FSRS_GRADUATE) return { mastered: true, itv };
  st.due = now + itv * 86400000;
  return { mastered: false, itv };
}

/* ---------- 今日待复习推荐队列 ---------- */
// 过滤出当前算法下「今天应复习」的单词（调用方传入已剔除已掌握的候选）
//  - wrong3: 全量推荐
//  - eb/fsrs: 仅到期的词，按到期时间升序
function queueFor(wordObjs) {
  const algo = currentAlgo();
  if (algo === 'wrong3') return wordObjs.slice();
  const now = Date.now();
  return wordObjs
    .map((w) => ({ w, due: dueTs(w.word) }))
    .filter((x) => x.due <= now)
    .sort((a, b) => a.due - b.due)
    .map((x) => x.w);
}

// 每日学习总量配额：不重复单词计数；今天已计入的词免费放行（艾宾浩斯/FSRS 当天多轮复习不受限）
// 会把新计入的词写入 progress.daily.words，调用方负责 saveProgress
function assignQuota(cands) {
  const p = progress();
  const s = (window.APP && window.APP.settings) || {};
  const total = Number(s.dailyTotal) || 500;
  if (!p.daily.words) p.daily.words = [];
  const used = new Set(p.daily.words);
  let free = Math.max(0, total - used.size);
  const out = [];
  for (const w of cands) {
    const lw = lwOf(w.word);
    if (used.has(lw)) { out.push(w); continue; }
    if (free <= 0) continue;
    out.push(w);
    p.daily.words.push(lw);
    free--;
  }
  return out;
}

// 今天剩余可学的不重复单词数
function dailyRemain() {
  const p = progress();
  const s = (window.APP && window.APP.settings) || {};
  const total = Number(s.dailyTotal) || 500;
  return Math.max(0, total - ((p.daily && p.daily.words) || []).length);
}

/* ---------- 进度标签（列表展示用） ---------- */
function describeDue(ts) {
  const diff = ts - Date.now();
  if (diff <= 0) return '待复习';
  const min = Math.ceil(diff / 60000);
  if (min < 60) return min + '分钟后';
  const h = Math.ceil(min / 60);
  if (h < 24) return h + '小时后';
  const d = new Date(ts);
  return (d.getMonth() + 1) + '月' + d.getDate() + '日';
}

// wrong3 返回 null（由调用方用 wrongRound/nbRound 展示）
function schedInfo(word) {
  const algo = currentAlgo();
  const st = stOf(word);
  if (algo === 'ebbinghaus') {
    const stage = st ? (st.stage || 0) : 0;
    const due = st ? (st.due || 0) : 0;
    return {
      text: '第' + Math.min(stage + 1, EB_TOTAL) + '/' + EB_TOTAL + '轮 · ' + (due <= Date.now() ? '待复习' : describeDue(due)),
      done: stage >= EB_TOTAL,
    };
  }
  if (algo === 'fsrs') {
    if (!st || !st.reps) return { text: '待首轮学习 · 强度未知', done: false };
    const itvTxt = st.itv >= 1 ? st.itv + ' 天' : FSRS_AGAIN_MIN + ' 分钟';
    return { text: '强度 ' + itvTxt + ' · ' + (st.due <= Date.now() ? '待复习' : describeDue(st.due)), done: false };
  }
  return null;
}



function normalizeInput(s) { return (s || '').toLowerCase().replace(/[\s'’]/g, '').trim(); }

// 题型引擎：闪记 → 测试（英译中10选1 / 中译英填空 / 例句完形4选1）
// 题型细节与阅读记保持一致
function runStudy(view, ctx, words, title) {
  // 过滤已掌握
  const activeWords = words.filter((w) => !(window.APP.progress.mastered && window.APP.progress.mastered[w.word.toLowerCase()]));
  if (!activeWords.length) { view.innerHTML = '<div class="card">' + IC.checkSm + '本组单词已全部掌握</div>'; return; }
  let mode = 'flash'; // flash | test | done
  let quizType = 'en2zh'; // en2zh | zh2en | cloze
  let idx = 0;
  const learnedWords = new Set();
  const sessionWrong = new Set();
  let quizState = null;

  const TYPE_LABELS = { en2zh: '英译中', zh2en: '中译英', cloze: '完形填空' };
  function typeBar() {
    return `<div class="reading-mode-bar">` + Object.keys(TYPE_LABELS).map((k) =>
      `<button class="mode-btn ${quizType === k ? 'on' : ''}" data-type="${k}">${TYPE_LABELS[k]}</button>`).join('') + `</div>`;
  }
  function bindTypeBar() {
    view.querySelectorAll('.mode-btn').forEach((b) => b.addEventListener('click', () => {
      quizType = b.dataset.type;
      if (mode === 'test') quizState = makeQuiz(activeWords[idx]);
      render();
    }));
  }

  function render() {
    if (mode === 'flash') return renderFlash();
    if (mode === 'test') return renderTest();
    return renderDone();
  }

  function renderFlash() {
    view.innerHTML = `
      <div class="card">
        <div class="between"><h2>${IC.grid}${escapeHtml(title)} · 闪记</h2><span class="pill">${idx + 1}/${activeWords.length}</span></div>
        <div class="hint">先快速过一遍，点击 ${IC.volumeSm} 听发音，再选练习类型开始测试。</div>
        ${typeBar()}
      </div>
      <div id="flashWrap"></div>
      <div class="row mt">
        <button class="btn gray block" id="prev">上一张</button>
        <button class="btn ghost block" id="next">下一张</button>
      </div>
      <button class="btn block mt" id="toTest">${IC.checkSm}开始测试（${TYPE_LABELS[quizType]}）</button>
    `;
    const wrap = view.querySelector('#flashWrap');
    wrap.innerHTML = wordCardHTML(activeWords[idx], { showNote: true });
    bindWordCardEvents(wrap, ctx);
    bindTypeBar();
    view.querySelector('#prev').onclick = () => { idx = (idx - 1 + activeWords.length) % activeWords.length; renderFlash(); };
    view.querySelector('#next').onclick = () => { idx = (idx + 1) % activeWords.length; renderFlash(); };
    view.querySelector('#toTest').onclick = () => { mode = 'test'; idx = 0; quizState = makeQuiz(activeWords[idx]); render(); };
  }

  function makeQuiz(word) {
    const lib = window.APP.library;
    if (quizType === 'zh2en') {
      return { word, type: 'zh2en', chosen: null };
    }
    if (quizType === 'en2zh') {
      const distract = pickDistractors(lib.words, word.word, 'meaning', 9);
      const options = shuffle([word.meaning, ...distract.filter(Boolean)]).slice(0, 10);
      return { word, type: 'en2zh', options, answer: word.meaning, chosen: null };
    }
    // 完形：例句挖空
    const ex = word.example || '';
    const w = word.word;
    const re = new RegExp('\\b' + w + '\\b', 'i');
    let sentence = ex, blankOk = false;
    if (re.test(ex)) { sentence = ex.replace(re, '______'); blankOk = true; }
    else { sentence = ex + ' （核心词：' + w + '）'; }
    const distract = pickDistractors(lib.words, word.word, 'word', 3);
    const options = shuffle([w, ...distract.filter(Boolean)]).slice(0, 4);
    return { word, type: 'cloze', sentence, blankOk, options, answer: w, chosen: null };
  }

  function renderTest() {
    const q = quizState;
    const w = q.word;
    const head = `<div class="card"><div class="between"><h2>${IC.pencil}测试 · ${escapeHtml(title)}</h2><span class="pill">${idx + 1}/${activeWords.length}</span></div>${typeBar()}</div>`;
    let body = '';
    if (q.type === 'en2zh') {
      const uk = formatPhonetic(w.phoneticUk || w.phonetic || '');
      const us = formatPhonetic(w.phoneticUs || '');
      body = `
        <div class="card">
          <div class="word-main">${escapeHtml(w.word)}</div>
          <div class="word-phon cols">
            ${uk ? `<span class="phon-tag">英</span><span class="audio-btn mini" data-act="uk" data-word="${escapeHtml(w.word)}">${IC.volumeSm}</span><span class="phon-uk">${uk}</span>` : ''}
            ${us ? `<span class="phon-tag us">美</span><span class="audio-btn mini" data-act="us" data-word="${escapeHtml(w.word)}">${IC.volumeSm}</span><span class="phon-us">${us}</span>` : ''}
          </div>
          <div class="hint mt">选出正确中文释义：</div>
          <div id="opts">${q.options.map((o, i) => `<button class="opt" data-i="${i}">${formatMeaningHTML(o)}</button>`).join('')}</div>
          <div id="explain" class="example mt" style="display:none"></div>
        </div>`;
    } else if (q.type === 'zh2en') {
      body = `
        <div class="card">
          <div class="hint">请根据中文释义写出对应的英文单词：</div>
          <div class="meaning" style="font-size:18px;margin:16px 0">${formatMeaningHTML(w.meaning || '')}</div>
          <input type="text" class="typing" id="ans" placeholder="输入英文单词" autocomplete="off" autocorrect="off" spellcheck="false">
          <div id="feedback" class="mt" style="min-height:24px"></div>
          <button class="btn block mt" id="check">检查</button>
          <button class="btn gray block mt" id="skip" style="display:none">下一题 →</button>
        </div>`;
    } else {
      body = `
        <div class="card">
          <div class="hint">完形填空：选出合适的单词填入空白处</div>
          <div class="example" style="font-size:17px;line-height:1.9">${escapeHtml(q.sentence)}</div>
          <div id="opts">${q.options.map((o, i) => `<button class="opt" data-i="${i}">${escapeHtml(o)}</button>`).join('')}</div>
          <div id="explain" class="example mt" style="display:none"></div>
        </div>`;
    }
    view.innerHTML = head + body + `<button class="btn block mt" id="next2" ${q.type === 'zh2en' ? 'style="display:none"' : 'disabled'}>下一题 →</button>`;
    bindTypeBar();
    view.querySelectorAll('[data-act="uk"]').forEach((b) => b.onclick = () => ctx.playUK(b.dataset.word));
    view.querySelectorAll('[data-act="us"]').forEach((b) => b.onclick = () => ctx.playUS(b.dataset.word));

    if (q.type === 'zh2en') {
      const input = view.querySelector('#ans');
      input.focus();
      const check = () => {
        if (q.chosen !== null) return;
        const ok = normalizeInput(input.value) === normalizeInput(w.word);
        const fb = view.querySelector('#feedback');
        if (ok) {
          fb.innerHTML = `<span style="color:var(--ok);font-weight:700">${IC.checkSm}正确！</span>`;
        } else {
          fb.innerHTML = `<span style="color:var(--warn);font-weight:700">${IC.xSm}正确答案：${escapeHtml(w.word)}</span>`;
          sessionWrong.add(w.word);
        }
        // 三项门控：中译英 / 英译中 / 完形 三项全对才判定掌握
        ctx.recordTask(w.word, 'zh2en', ok);
        learnedWords.add(w.word);
        q.chosen = input.value;
        view.querySelector('#check').style.display = 'none';
        const skip = view.querySelector('#skip');
        skip.style.display = 'block';
        skip.textContent = idx < activeWords.length - 1 ? '下一题 →' : '完成';
        skip.onclick = () => advance();
        input.blur();
      };
      view.querySelector('#check').onclick = check;
      input.addEventListener('keydown', (ev) => { if (ev.key === 'Enter') check(); });
      return;
    }

    const opts = view.querySelectorAll('.opt');
    opts.forEach((btn) => btn.addEventListener('click', () => {
      if (q.chosen !== null) return;
      const val = q.options[+btn.dataset.i];
      const correct = (val === q.answer);
      opts.forEach((b) => {
        const bv = q.options[+b.dataset.i];
        if (bv === q.answer) b.classList.add('correct');
        else if (b === btn) b.classList.add('wrong');
        b.disabled = true;
      });
      const exp = view.querySelector('#explain');
      exp.style.display = 'block';
      if (q.type === 'en2zh') {
        exp.innerHTML = (correct ? IC.checkSm + '正确！ ' : IC.xSm + '正确答案：' + escapeHtml(q.answer) + '。 ') + formatMeaningHTML(w.meaning);
      } else {
        exp.innerHTML = correct ? IC.checkSm + '正确！' : IC.xSm + '正确答案：' + escapeHtml(q.answer);
      }
      learnedWords.add(w.word);
      if (!correct) sessionWrong.add(w.word);
      // 三项门控：中译英 / 英译中 / 完形 三项全对才判定掌握
      ctx.recordTask(w.word, q.type, correct);
      q.chosen = val;
      const next = view.querySelector('#next2');
      next.style.display = 'block';
      next.disabled = false;
      next.onclick = () => advance();
      // 自动跳转（与阅读记一致）
      const delay = q.type === 'en2zh' ? 900 : 1100;
      setTimeout(() => { if (quizState === q && q.chosen === val) advance(); }, delay);
    }));
  }

  function advance() {
    idx++;
    if (idx >= activeWords.length) { mode = 'done'; render(); return; }
    quizState = makeQuiz(activeWords[idx]); render();
  }

  function renderDone() {
    const w = activeWords.length;
    const mastered = Object.keys(window.APP.progress.mastered).length;
    // 只累计曝光轮次；掌握判定统一由三项门控 recordTask 负责
    ctx.completeReadingSession(activeWords.map((w) => w.word), sessionWrong);
    view.innerHTML = `
      <div class="card" style="text-align:center">
        <h2>${IC.checkSm}本轮完成！</h2>
        <div class="stat-grid">
          <div class="stat"><div class="num">${w}</div><div class="lab">本组单词</div></div>
          <div class="stat"><div class="num warn">+${learnedWords.size}</div><div class="lab">学习星数 ${IC.starSm}</div></div>
          <div class="stat"><div class="num">${mastered}</div><div class="lab">累计掌握</div></div>
        </div>
        <div class="hint mt">本轮学习已计入星级与掌握进度；答错的词已自动进入「错词本」。</div>
        <button class="btn block mt" id="again">${IC.rotateSm}再练一轮</button>
        <button class="btn gray block mt" id="back">返回</button>
      </div>`;
    view.querySelector('#again').onclick = () => { mode = 'flash'; idx = 0; sessionWrong.clear(); learnedWords.clear(); render(); };
    view.querySelector('#back').onclick = () => window.dispatchEvent(new CustomEvent('goto', { detail: window.APP.page }));
  }

  render();
}


/**
 * 单词练习引擎（与阅读记「单词闪记 / 中译英 / 英译中 / 完形填空」题型与节奏一致）。
 * 用于生词本 / 错题本等「单词列表」型专项复习，使其练习方式与阅读记单词对齐。
 * 阅读记本身仍使用 modules/reading.js 内的实现（含文章例句完形），本引擎为通用词表版。
 */

function normalizeInput(s) { return (s || '').toLowerCase().replace(/[\s'’]/g, '').trim(); }

function runWordQuiz(ctx, view, words, title, opts = {}) {
  const getSentence = opts.getSentence || ((w) => w.example || '');
  const pool = opts.pool || words;
  // 支持「按轮次动态获取单词」（如错词本每天每词只刷一轮）：getWords 每次重练时重新计算候选集。
  const getWords = opts.getWords || (() => words);
  // activeWords 在每轮开始时由 getWords 重新计算（错词本：剔除当天已练过的词）
  let activeWords = [];
  function computeActive() {
    const ws = getWords();
    // 默认过滤已掌握；错词本需练满「连续全对 3 轮」才移出，因此必须保留已判掌握的词
    return opts.includeMastered
      ? ws.slice()
      : ws.filter((w) => !(window.APP.progress.mastered && window.APP.progress.mastered[w.word.toLowerCase()]));
  }
  let mode = 'flash'; // flash | test | done
  let quizType = 'en2zh'; // en2zh | zh2en | cloze
  let idx = 0;
  const learnedWords = new Set();
  const sessionWrong = new Set();
  let quizState = null;

  const TYPE_LABELS = { en2zh: '英译中', zh2en: '中译英', cloze: '完形填空' };
  function typeBar() {
    return `<div class="reading-mode-bar">` + Object.keys(TYPE_LABELS).map((k) =>
      `<button class="mode-btn ${quizType === k ? 'on' : ''}" data-type="${k}">${TYPE_LABELS[k]}</button>`).join('') + `</div>`;
  }
  function bindTypeBar() {
    view.querySelectorAll('.mode-btn').forEach((b) => b.addEventListener('click', () => {
      quizType = b.dataset.type;
      if (mode === 'test') quizState = makeQuiz(activeWords[idx]);
      render();
    }));
  }

  function render() {
    if (mode === 'flash') return renderFlash();
    if (mode === 'test') return renderTest();
    return renderDone();
  }

  // 开始一轮练习：重新计算本轮单词（错词本会剔除当天已练过的词）。
  // onStart 在真正进入本轮时回调（错词本借此把本轮单词记入「当天已练」集合，确保每天每词只刷一轮）。
  function startRound() {
    activeWords = computeActive();
    if (!activeWords.length) {
      const msg = opts.onStart
        ? '这些词今天都已经练过一轮啦，明天再来～'
        : IC.checkSm + '本组单词已全部掌握';
      view.innerHTML = '<div class="card" style="text-align:center">' + msg + '<br/><button class="btn gray block mt" id="back">返回</button></div>';
      view.querySelector('#back').onclick = () => window.dispatchEvent(new CustomEvent('goto', { detail: window.APP.page }));
      return;
    }
    mode = 'flash'; idx = 0; learnedWords.clear(); sessionWrong.clear();
    if (opts.onStart) { try { opts.onStart(activeWords); } catch (e) { /* ignore */ } }
    render();
  }

  /* ---------- 闪记 ---------- */
  function renderFlash() {
    view.innerHTML = `
      <div class="card">
        <div class="between"><h2>${IC.zap}${escapeHtml(title)} · 闪记</h2><span class="pill">${idx + 1}/${activeWords.length}</span></div>
        <div class="hint">先快速过一遍，点击 ${IC.volumeSm} 听发音，再选练习类型开始测试。</div>
        ${typeBar()}
      </div>
      <div class="flash-wrap">
        <button class="flash-arrow left" id="arrowPrev" aria-label="上一个">‹</button>
        <div id="flashCard"></div>
        <button class="flash-arrow right" id="arrowNext" aria-label="下一个">›</button>
      </div>
      <div class="row mt">
        <button class="btn gray block" id="prev">上一张</button>
        <button class="btn ghost block" id="next">下一张</button>
      </div>
      <button class="btn block mt" id="toTest">${IC.checkSm}开始测试（${TYPE_LABELS[quizType]}）</button>
    `;
    const wrap = view.querySelector('#flashCard');
    wrap.innerHTML = wordCardHTML(activeWords[idx], { showNote: true });
    bindWordCardEvents(wrap, ctx);
    bindTypeBar();
    ctx.playUK(activeWords[idx].word);
    const goPrev = () => { idx = (idx - 1 + activeWords.length) % activeWords.length; renderFlash(); };
    const goNext = () => { idx = (idx + 1) % activeWords.length; renderFlash(); };
    view.querySelector('#prev').onclick = goPrev;
    view.querySelector('#next').onclick = goNext;
    const ap = view.querySelector('#arrowPrev'); if (ap) ap.onclick = goPrev;
    const an = view.querySelector('#arrowNext'); if (an) an.onclick = goNext;
    view.querySelector('#toTest').onclick = () => { mode = 'test'; idx = 0; quizState = makeQuiz(activeWords[idx]); render(); };
  }

  /* ---------- 出题 ---------- */
  function makeQuiz(word) {
    if (quizType === 'zh2en') return { word, type: 'zh2en', chosen: null };
    if (quizType === 'en2zh') {
      // 中文选项用「常用译文」（取首义项），避免一长串义项；并去重
      const cand = pool.filter((x) => x.word !== word.word && x.meaning);
      const options = buildEn2ZhOptions(word.meaning, cand, 10);
      return { word, type: 'en2zh', options, answer: commonMeaning(word.meaning) || word.meaning, chosen: null };
    }
    // 完形：例句挖空（优先该词自身例句；无例句则提示核心词）
    const ex = getSentence(word) || '';
    const w = word.word;
    const re = new RegExp('\\b' + w + '\\b', 'i');
    let sentence = ex, blankOk = false;
    if (re.test(ex)) { sentence = ex.replace(re, '______'); blankOk = true; }
    else { sentence = ex + ' （核心词：' + w + '）'; }
    const distract = shuffle(pool.filter((x) => x.word !== word.word)).slice(0, 3).map((x) => x.word);
    const options = shuffle([w, ...distract]).slice(0, 4);
    return { word, type: 'cloze', sentence, blankOk, options, answer: w, chosen: null };
  }

  /* ---------- 测试 ---------- */
  function renderTest() {
    const q = quizState;
    const w = q.word;
    const head = `<div class="card"><div class="between"><h2>${IC.pencil}测试 · ${escapeHtml(title)}</h2><span class="pill">${idx + 1}/${activeWords.length}</span></div>${typeBar()}</div>`;
    let body = '';
    if (q.type === 'en2zh') {
      const uk = formatPhonetic(w.phoneticUk || w.phonetic || '');
      const us = formatPhonetic(w.phoneticUs || '');
      body = `
        <div class="card">
          <div class="word-main">${escapeHtml(w.word)}</div>
          <div class="word-phon cols">
            ${uk ? `<span class="phon-tag">英</span><span class="audio-btn mini" data-act="uk" data-word="${escapeHtml(w.word)}">${IC.volumeSm}</span><span class="phon-uk">${uk}</span>` : ''}
            ${us ? `<span class="phon-tag us">美</span><span class="audio-btn mini" data-act="us" data-word="${escapeHtml(w.word)}">${IC.volumeSm}</span><span class="phon-us">${us}</span>` : ''}
          </div>
          <div class="hint mt">选出正确中文释义：</div>
          <div id="opts">${q.options.map((o, i) => `<button class="opt" data-i="${i}">${formatMeaningHTML(o)}</button>`).join('')}</div>
          <div id="explain" class="example mt" style="display:none"></div>
        </div>`;
    } else if (q.type === 'zh2en') {
      body = `
        <div class="card">
          <div class="hint">请根据中文释义写出对应的英文单词：</div>
          <div class="meaning" style="font-size:18px;margin:16px 0">${formatMeaningHTML(w.meaning || '')}</div>
          <input type="text" class="typing" id="ans" placeholder="输入英文单词" autocomplete="off" autocorrect="off" spellcheck="false">
          <div id="feedback" class="mt" style="min-height:24px"></div>
          <button class="btn block mt" id="check">检查</button>
          <button class="btn gray block mt" id="skip" style="display:none">下一题 →</button>
        </div>`;
    } else {
      body = `
        <div class="card">
          <div class="hint">完形填空：选出合适的单词填入空白处</div>
          <div class="example" style="font-size:17px;line-height:1.9">${escapeHtml(q.sentence)}</div>
          <div id="opts">${q.options.map((o, i) => `<button class="opt" data-i="${i}">${escapeHtml(o)}</button>`).join('')}</div>
          <div id="explain" class="example mt" style="display:none"></div>
        </div>`;
    }
    view.innerHTML = head + body + `<button class="btn block mt" id="next2" ${q.type === 'zh2en' ? 'style="display:none"' : 'disabled'}>下一题 →</button>`;
    bindTypeBar();
    view.querySelectorAll('[data-act="uk"]').forEach((b) => b.onclick = () => ctx.playUK(b.dataset.word));
    view.querySelectorAll('[data-act="us"]').forEach((b) => b.onclick = () => ctx.playUS(b.dataset.word));

    if (q.type === 'zh2en') {
      const input = view.querySelector('#ans');
      input.focus();
      const check = () => {
        if (q.chosen !== null) return;
        const ok = normalizeInput(input.value) === normalizeInput(w.word);
        const fb = view.querySelector('#feedback');
        if (ok) {
          fb.innerHTML = `<span style="color:var(--ok);font-weight:700">${IC.checkSm}正确！</span>`;
        } else {
          fb.innerHTML = `<span style="color:var(--warn);font-weight:700">${IC.xSm}正确答案：${escapeHtml(w.word)}</span>`;
          sessionWrong.add(w.word);
          ctx.recordWrongQuestion({ word: w.word, type: 'zh2en', typeLabel: '中译英', prompt: w.meaning, choices: null, answer: w.word, user: input.value, ts: Date.now() });
        }
        // 三项门控：中译英 / 英译中 / 完形 三项全对才判定掌握
        ctx.recordTask(w.word, 'zh2en', ok);
        learnedWords.add(w.word);
        q.chosen = input.value;
        view.querySelector('#check').style.display = 'none';
        const skip = view.querySelector('#skip');
        skip.style.display = 'block';
        skip.textContent = idx < activeWords.length - 1 ? '下一题 →' : '完成';
        skip.onclick = () => advance();
        input.blur();
      };
      view.querySelector('#check').onclick = check;
      input.addEventListener('keydown', (ev) => { if (ev.key === 'Enter') check(); });
      return;
    }

    const opts = view.querySelectorAll('.opt');
    opts.forEach((btn) => btn.addEventListener('click', () => {
      if (q.chosen !== null) return;
      const val = q.options[+btn.dataset.i];
      const correct = (val === q.answer);
      opts.forEach((b) => {
        const bv = q.options[+b.dataset.i];
        if (bv === q.answer) b.classList.add('correct');
        else if (b === btn) b.classList.add('wrong');
        b.disabled = true;
      });
      const exp = view.querySelector('#explain');
      exp.style.display = 'block';
      if (q.type === 'en2zh') {
        exp.innerHTML = (correct ? IC.checkSm + '正确！ ' : IC.xSm + '正确答案：' + escapeHtml(q.answer) + '。 ') + formatMeaningHTML(w.meaning);
      } else {
        exp.innerHTML = correct ? IC.checkSm + '正确！' : IC.xSm + '正确答案：' + escapeHtml(q.answer);
      }
      learnedWords.add(w.word);
      if (!correct) {
        sessionWrong.add(w.word);
        // 记录做错的「题」（英译中 / 完形填空），仅供历史追溯
        ctx.recordWrongQuestion({
          word: q.word, type: q.type,
          typeLabel: q.type === 'en2zh' ? '英译中' : '完形填空',
          prompt: q.type === 'en2zh' ? q.word : q.sentence,
          choices: q.options, answer: q.answer, user: val, ts: Date.now(),
        });
      }
      // 三项门控：中译英 / 英译中 / 完形 三项全对才判定掌握（生词本/错词本按算法分派）
      ctx.recordTask(w.word, q.type, correct, source);
      q.chosen = val;
      const next = view.querySelector('#next2');
      next.style.display = 'block';
      next.disabled = false;
      next.onclick = () => advance();
      // 自动跳转（与阅读记一致）
      const delay = q.type === 'en2zh' ? 900 : 1100;
      setTimeout(() => { if (quizState === q && q.chosen === val) advance(); }, delay);
    }));
  }

  function advance() {
    idx++;
    if (idx >= activeWords.length) { mode = 'done'; render(); return; }
    quizState = makeQuiz(activeWords[idx]); render();
  }

  function renderDone() {
    const w = activeWords.length;
    const mastered = Object.keys(window.APP.progress.mastered).length;
    // 只累计曝光轮次；掌握判定统一由三项门控 recordTask 负责
    ctx.completeReadingSession(activeWords.map((w) => w.word), sessionWrong);
    view.innerHTML = `
      <div class="card" style="text-align:center">
        <h2>${IC.checkSm}本轮完成！</h2>
        <div class="stat-grid">
          <div class="stat"><div class="num">${w}</div><div class="lab">本组单词</div></div>
          <div class="stat"><div class="num warn">+${learnedWords.size}</div><div class="lab">学习星数 ${IC.starSm}</div></div>
          <div class="stat"><div class="num">${mastered}</div><div class="lab">累计掌握</div></div>
        </div>
        <div class="hint mt">本轮学习已计入星级与掌握进度；答错的词已自动进入「错词本」。</div>
        <button class="btn block mt" id="again">${IC.rotateSm}再练一轮</button>
        <button class="btn gray block mt" id="back">返回</button>
      </div>`;
    view.querySelector('#again').onclick = () => { startRound(); };
    view.querySelector('#back').onclick = () => window.dispatchEvent(new CustomEvent('goto', { detail: window.APP.page }));
  }

  startRound();
}




function isMastered(word) {
  return !!(window.APP && window.APP.progress && window.APP.progress.mastered && window.APP.progress.mastered[word.toLowerCase()]);
}

/* ---------- 分类扩展数据（考频/词根/相似/象形）懒加载 ---------- */
let _tax = null;
let _taxPromise = null;
function loadTax() {
  if (_tax) return Promise.resolve(_tax);
  if (!_taxPromise) {
    _taxPromise = safeFetch('/data/taxonomy.json')
      .then((r) => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
      .then((t) => { _tax = t; return t; })
      .catch((e) => { _taxPromise = null; throw e; });
  }
  return _taxPromise;
}

// 象形记精确配图清单：单词 -> vxiaozhi 助记图 URL。
// 数据来源 https://github.com/vxiaozhi/vocabulary-book-by-deepseek（已上线 https://word.vxiaozhi.com），
// 每个单词由 AI 按其词义生成一张助记图像，按「字母/单词.jpg」命名，对应精准、远优于 emoji/语义标签取图。
// 清单由 tools/build_vxiaozhi_pict.js 依据本词库与 vxiaozhi 词表交集生成（word -> 远程图 URL），这里只读取。
let _pictImgs = null; // Map<wordLower, url>
function loadPictImages() {
  if (_pictImgs) return Promise.resolve(_pictImgs);
  _pictImgs = new Map();
  return safeFetch('/data/pict_images.json?v=20260911b')
    .then((r) => (r.ok ? r.json() : {}))
    .then((obj) => { Object.entries(obj || {}).forEach(([w, url]) => _pictImgs.set(String(w).toLowerCase(), url)); return _pictImgs; })
    .catch(() => _pictImgs);
}
// 取单词的 vxiaozhi 精确助记图 URL（无则 null），供象形记优先显示
function vxImgURL(w) {
  if (!_pictImgs || !w) return null;
  return _pictImgs.get(String(w).toLowerCase()) || null;
}

let _wmap = null;
function wordMap(APP) {
  if (!_wmap) {
    _wmap = new Map();
    for (const w of (APP.library.words || [])) _wmap.set(w.word.toLowerCase(), w);
  }
  return _wmap;
}
function resolveWords(APP, list) {
  const m = wordMap(APP);
  return (list || []).map((k) => m.get(String(k).toLowerCase())).filter(Boolean);
}
const FREQ_TIERS = [
  { k: 'hot', name: '高频核心', desc: '词频榜前 3000 · 考试最常考', test: (r) => r <= 3000 },
  { k: 'mid', name: '常用进阶', desc: '词频榜 3001-6000 · 阅读常客', test: (r) => r > 3000 && r <= 6000 },
  { k: 'low', name: '低频扩展', desc: '词频榜 6000 以后 · 拔高词汇', test: (r) => r > 6000 },
  { k: 'off', name: '榜外生词', desc: '未进入万词榜 · 专业/超纲词', test: () => true },
];
const PICT_ICONS = { '动物与自然': '🐻', '食物与饮品': '🍎', '人物与身体': '🧑', '物品与工具': '🔧', '活动与运动': '⚽', '旅行与地点': '✈', '情感与表情': '😀', '符号': '🔣', '图标简笔': '🖍️', '义符': '🔤', '其他': '✨' };
// 象形记总数：emoji 图记 + 线性图标简笔
function pictTotal(tax) { return Object.keys(tax.pict || {}).length + Object.keys(tax.pictIcon || {}).length; }
// 线性图标简笔 SVG（phosphor 为填充型，其余为描边型，分别处理以保证都能渲染）
function iconSvg(v) {
  if (!v) return '';
  const [coll, , body, iw, ih] = v;
  const stroke = coll !== 'ph';
  return `<svg class="p-svg" viewBox="0 0 ${iw || 24} ${ih || 24}" fill="${stroke ? 'none' : 'currentColor'}" stroke="${stroke ? 'currentColor' : 'none'}" stroke-width="${stroke ? 1.8 : 0}" stroke-linecap="round" stroke-linejoin="round">${body}</svg>`;
}
// 人教版高中册顺序（与听写模块保持一致），用于单元排序与分组
const HS_BOOKS = ['必修一', '必修二', '必修三', '选必一', '选必二', '选必三', '选必四'];
function hsUnitSortKey(u) {
  if (!u) return [99, 99];
  const wm = /^(.+?)\s*Welcome\s*Unit$/i.exec(u);
  if (wm) return [HS_BOOKS.indexOf(wm[1]), -1];
  const m = /^([^U]+)U(\d+)$/.exec(u);
  if (!m) return [99, 99];
  return [HS_BOOKS.indexOf(m[1]), Number(m[2])];
}
// 收集高中各单元单词，按「册 -> 单元」分组（Welcome Unit 置于该册最前）
function hsUnitGroups(APP) {
  const byUnit = {};
  for (const w of (APP.library.words || [])) {
    const p = w.pep;
    if (p && p.band === '高中' && p.unit) (byUnit[p.unit] = byUnit[p.unit] || []).push(w);
  }
  const books = {};
  for (const u of Object.keys(byUnit)) {
    const sk = hsUnitSortKey(u);
    const m = /^(.+?)\s*Welcome\s*Unit$/i.exec(u);
    const book = m ? m[1] : (u.replace(/U\d+$/, '') || '其他');
    if (!books[book]) books[book] = { order: sk[0], units: [] };
    books[book].units.push({ unit: u, words: byUnit[u], sk });
  }
  const list = Object.keys(books).map((b) => books[b]).sort((a, b) => a.order - b.order);
  list.forEach((bk) => bk.units.sort((a, b) => a.sk[0] - b.sk[0] || a.sk[1] - b.sk[1]));
  return list;
}

const __mod_category = {
  render({ view, APP, ctx }) {
    const words = (APP.library && APP.library.words) || [];
    const groups = {};
    words.forEach((w) => {
      const cat = w.category || '未分类';
      if (!groups[cat]) groups[cat] = [];
      groups[cat].push(w);
    });
    const cats = Object.keys(groups).sort((a, b) => {
      if (a === '未分类') return 1;
      if (b === '未分类') return -1;
      return a.localeCompare(b, 'zh-CN');
    });
    if (!cats.length) {
      view.innerHTML = '<div class="card">词库暂无数据，请到「导入」添加单词。</div>';
      return;
    }
    // 高中分单元：统计单元数与待练数
    const hsGroups = hsUnitGroups(APP);
    let hsUnits = 0, hsActive = 0;
    hsGroups.forEach((bk) => bk.units.forEach((u) => {
      hsUnits++;
      hsActive += u.words.filter((w) => !isMastered(w.word) && ctx.matchDifficulty(w)).length;
    }));
    const TAX_CARDS = [
      { kind: 'unit', icon: IC.bookSm, name: '单元记', desc: hsUnits + ' 个教材单元', badge: hsActive ? hsActive + ' 词待练' : '按册逐单元练' },
      { kind: 'pict', icon: '🧩', name: '象形记', desc: '图像联想记忆', badge: '加载中…' },
      { kind: 'roots', icon: IC.bookOpenSm, name: '词根记', desc: '词根词缀拆词', badge: '加载中…' },
      { kind: 'freq', icon: IC.chartSm, name: '考频记', desc: '按考试词频分层', badge: '加载中…' },
      { kind: 'similar', icon: IC.targetSm, name: '相似记', desc: '易混词对比记', badge: '加载中…' },
    ];
    view.innerHTML = `
      <div class="section-title"><svg class="vico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3.5" y="3.5" width="7" height="7" rx="1.6"/><rect x="13.5" y="3.5" width="7" height="7" rx="1.6"/><rect x="3.5" y="13.5" width="7" height="7" rx="1.6"/><rect x="13.5" y="13.5" width="7" height="7" rx="1.6"/></svg>分类记 · 共 ${cats.length} 个分类 / ${words.length} 词</div>
      <div class="tax-grid">
        ${TAX_CARDS.map((c) => `
        <div class="cat-card tax-card" data-tax="${c.kind}">
          <div class="c-name">${c.icon}${c.name}</div>
          <div class="c-count">${c.desc}</div>
          <span class="badge" data-taxbadge="${c.kind}">${c.badge}</span>
        </div>`).join('')}
      </div>
      <div class="section-title" style="margin-top:18px">${IC.grid}主题分类</div>
      <div class="cat-grid">
        ${cats.map((c) => {
          const all = groups[c];
          const active = all.filter((w) => !isMastered(w.word));
          const activeDiff = active.filter((w) => ctx.matchDifficulty(w));
          const masteredCount = all.length - active.length;
          const badge = activeDiff.length ? `${activeDiff.length} 词待练` : '当前难度无待练';
          return `
          <div class="cat-card" data-cat="${escapeHtml(c)}">
            <div class="c-name">${escapeHtml(c)}</div>
            <div class="c-count">${all.length} 词${masteredCount ? ` · 已掌握 ${masteredCount}` : ''}</div>
            <span class="badge">${badge}</span>
          </div>`;
        }).join('')}
      </div>
    `;
    view.querySelectorAll('.cat-card').forEach((card) => {
      if (card.dataset.tax) {
        card.addEventListener('click', () => openTaxSub(view, ctx, APP, card.dataset.tax));
        return;
      }
      card.addEventListener('click', () => {
        const cat = card.dataset.cat;
        const active = groups[cat].filter((w) => !isMastered(w.word) && ctx.matchDifficulty(w));
        if (!active.length) { ctx.toast('该分类在当前难度下暂无待练单词 🎉'); return; }
        openCategory(view, ctx, cat, active);
      });
    });
    // 异步填充五张入口卡的统计
    loadTax().then((tax) => {
      const m = wordMap(APP);
      const act = (k) => resolveWords(APP, k).filter((w) => !isMastered(w.word) && ctx.matchDifficulty(w));
      const set = (kind, text) => {
        const el = view.querySelector(`[data-taxbadge="${kind}"]`);
        if (el) el.textContent = text;
      };
      if (!view.isConnected) return;
      set('pict', pictTotal(tax) + ' 词有图记');
      set('roots', (tax.roots || []).length + ' 组词根词缀');
      const fc = FREQ_TIERS.map((t) => {
        const ws = Object.entries(tax.freq || {}).filter(([w, r]) => byWordIn(m, w) && t.test(r));
        return act(ws.map(([w]) => w)).length;
      }).reduce((a, b) => a + b, 0);
      set('freq', fc + ' 词待练');
      const sc = (tax.similar || []).filter((g) => act(g).length >= 2).length;
      set('similar', sc + ' 组易混词');
    }).catch(() => {
      ['pict', 'roots', 'freq', 'similar'].forEach((k) => {
        const el = view.querySelector(`[data-taxbadge="${k}"]`);
        if (el) el.textContent = '数据未加载';
      });
    });
  },
};

function byWordIn(m, w) { return m.has(w); }

/* ---------- 扩展子模块：单元记/象形记/词根记/考频记/相似记 ---------- */
function openTaxSub(view, ctx, APP, kind) {
  if (kind === 'unit') return openHSUnits(view, ctx, APP);
  view.innerHTML = '<div class="card">分类数据加载中…</div>';
  loadTax().then((tax) => {
    if (!view.isConnected) return;
    if (kind === 'roots') renderRoots(view, ctx, APP, tax, 'all');
    else if (kind === 'similar') renderSimilar(view, ctx, APP, tax);
    else if (kind === 'freq') renderFreq(view, ctx, APP, tax);
    else if (kind === 'pict') loadPictImages().then(() => renderPictCats(view, ctx, APP, tax)).catch(() => renderPictCats(view, ctx, APP, tax));
  }).catch(() => {
    view.innerHTML = '<div class="card">扩展分类数据加载失败，请通过服务器（而非本地文件）访问后重试。</div>';
  });
}
function backMain() { return () => window.dispatchEvent(new CustomEvent('goto', { detail: 'category' })); }

function renderRoots(view, ctx, APP, tax, filter) {
  const back = backMain();
  const types = [['all', '全部'], ['pre', '前缀'], ['root', '词根'], ['suf', '后缀']];
  const list = (tax.roots || []).filter((g) => filter === 'all' || !filter || g.t === filter);
  view.innerHTML = `
    <div class="section-title">${IC.bookOpen}词根记 · ${list.length} 组</div>
    <div class="card">
      <div class="between"><h2>词根词缀 · 拆词速记</h2><button class="btn sm ghost" id="back">返回分类</button></div>
      <p class="hint" style="margin-top:4px">掌握一个词根 = 串记一族单词。数据来源：开源英语词根库（1061 条）精选 + 词库匹配。</p>
      <div class="reading-mode-bar" style="margin-top:8px">
        ${types.map(([k, n]) => `<button class="mode-btn ${filter === k ? 'on' : ''}" data-rt="${k}">${n}</button>`).join('')}
      </div>
    </div>
    <div class="cat-grid">
      ${list.map((g) => {
        const act = resolveWords(APP, g.words).filter((w) => !isMastered(w.word) && ctx.matchDifficulty(w));
        return `<div class="cat-card" data-root="${escapeHtml(g.k)}" data-cn="${escapeHtml(g.cn)}">
          <div class="c-name">${escapeHtml(g.k)} <span class="rt-type t-${g.t}">${g.t === 'pre' ? '前缀' : g.t === 'suf' ? '后缀' : '词根'}</span></div>
          <div class="c-count">${escapeHtml(g.cn)}${g.en ? ' · ' + escapeHtml(g.en) : ''}</div>
          <span class="badge">${g.words.length} 词 · 待练 ${act.length}</span>
        </div>`;
      }).join('')}
    </div>`;
  view.querySelector('#back').onclick = back;
  view.querySelectorAll('[data-rt]').forEach((b) => b.addEventListener('click', () => renderRoots(view, ctx, APP, tax, b.dataset.rt)));
  view.querySelectorAll('.cat-card[data-root]').forEach((card) => {
    card.addEventListener('click', () => {
      const g = (tax.roots || []).find((x) => x.k === card.dataset.root);
      if (!g) return;
      const act = resolveWords(APP, g.words).filter((w) => !isMastered(w.word) && ctx.matchDifficulty(w));
      if (!act.length) { ctx.toast('该词根在当前难度下暂无待练单词 🎉'); return; }
      openCategory(view, ctx, `词根 ${g.k} · ${g.cn}`, act, () => renderRoots(view, ctx, APP, tax, filter));
    });
  });
  view.scrollTop = 0;
}

function renderSimilar(view, ctx, APP, tax) {
  const back = backMain();
  const groups = (tax.similar || [])
    .map((g) => ({ g, act: resolveWords(APP, g).filter((w) => !isMastered(w.word) && ctx.matchDifficulty(w)) }))
    .filter((x) => x.act.length >= 2);
  view.innerHTML = `
    <div class="section-title">${IC.target}相似记 · ${groups.length} 组易混词</div>
    <div class="card">
      <div class="between"><h2>相似词 · 对比速记</h2><button class="btn sm ghost" id="back">返回分类</button></div>
      <p class="hint" style="margin-top:4px">拼写只差一个字母的「双胞胎词」集中对比，一遍记牢、不再混淆（编辑距离算法自动聚类）。</p>
    </div>
    <div class="cat-grid">
      ${groups.map(({ g, act }) => `
      <div class="cat-card" data-sim="${escapeHtml(g.join(','))}">
        <div class="c-name sim-names">${g.map((w) => escapeHtml(w)).join('<i class="sep">/</i>')}</div>
        <span class="badge">${g.length} 词 · 待练 ${act.length}</span>
      </div>`).join('')}
    </div>`;
  view.querySelector('#back').onclick = back;
  view.querySelectorAll('.cat-card[data-sim]').forEach((card) => {
    card.addEventListener('click', () => {
      const g = card.dataset.sim.split(',');
      const act = resolveWords(APP, g).filter((w) => !isMastered(w.word) && ctx.matchDifficulty(w));
      if (act.length < 2) { ctx.toast('这组词在当前难度下暂无可练单词 🎉'); return; }
      openCategory(view, ctx, '相似记 · ' + g.slice(0, 3).join(' / ') + (g.length > 3 ? '…' : ''), act, () => renderSimilar(view, ctx, APP, tax));
    });
  });
  view.scrollTop = 0;
}

function renderFreq(view, ctx, APP, tax) {
  const back = backMain();
  const m = wordMap(APP);
  const tiers = FREQ_TIERS.map((t) => {
    let entries;
    if (t.k === 'off') {
      entries = [...m.keys()].filter((w) => !(tax.freq || {})[w]);
      entries.sort((a, b) => ((m.get(a).difficulty || 9) - (m.get(b).difficulty || 9)) || a.localeCompare(b));
    } else {
      entries = Object.entries(tax.freq || {}).filter(([w, r]) => m.has(w) && t.test(r))
        .sort((a, b) => a[1] - b[1]).map(([w]) => w);
    }
    const act = resolveWords(APP, entries).filter((w) => !isMastered(w.word) && ctx.matchDifficulty(w));
    return { ...t, words: entries, act };
  });
  view.innerHTML = `
    <div class="section-title">${IC.chart}考频记 · 按考试词频分层</div>
    <div class="card">
      <div class="between"><h2>考频分层 · 先啃高频词</h2><button class="btn sm ghost" id="back">返回分类</button></div>
      <p class="hint" style="margin-top:4px">依据 Google 万词频榜（开源语料统计）为词库标注考频层级：排名越靠前，考试出现概率越高。</p>
    </div>
    <div class="cat-grid">
      ${tiers.map((t) => `
      <div class="cat-card" data-tier="${t.k}">
        <div class="c-name">${t.name}</div>
        <div class="c-count">${t.desc}</div>
        <span class="badge">${t.words.length} 词 · 待练 ${t.act.length}</span>
      </div>`).join('')}
    </div>`;
  view.querySelector('#back').onclick = back;
  view.querySelectorAll('.cat-card[data-tier]').forEach((card) => {
    card.addEventListener('click', () => {
      const t = tiers.find((x) => x.k === card.dataset.tier);
      if (!t) return;
      if (!t.act.length) { ctx.toast('该层级在当前难度下暂无待练单词 🎉'); return; }
      let act = t.act;
      if (act.length > 600) { act = act.slice(0, 600); ctx.toast('词量较大，本次先练前 600 词'); }
      openCategory(view, ctx, `考频记 · ${t.name}`, act, () => renderFreq(view, ctx, APP, tax));
    });
  });
  view.scrollTop = 0;
}

function renderPictCats(view, ctx, APP, tax) {
  const back = backMain();
  const byCat = {};
  for (const [w, [e, c]] of Object.entries(tax.pict || {})) {
    if (!wordMap(APP).has(w)) continue;
    (byCat[c] = byCat[c] || []).push([w, e]);
  }
  for (const [w] of Object.entries(tax.pictIcon || {})) {
    if (!wordMap(APP).has(w) || tax.pict[w]) continue;
    (byCat['图标简笔'] = byCat['图标简笔'] || []).push([w, null]);
  }
  const cats = Object.keys(byCat).sort((a, b) => byCat[b].length - byCat[a].length);
  view.innerHTML = `
    <div class="section-title">🧩象形记 · ${pictTotal(tax)} 词有图记</div>
    <div class="card">
      <div class="between"><h2>象形图记 · 一图记一词</h2><button class="btn sm ghost" id="back">返回分类</button></div>
      <p class="hint" style="margin-top:4px">为单词配一幅「心理图像」，图像联想是最古老的记忆术。图源：vxiaozhi AI 助记图（每个单词一张按词义精确生成的配图，已上线 word.vxiaozhi.com）优先，缺图时回退 Unicode emoji 与 Tabler/Phosphor 开源简笔图标。</p>
    </div>
    <div class="cat-grid">
      ${cats.map((c) => {
        const preview = c === '图标简笔'
          ? iconSvg(tax.pictIcon[byCat[c][0][0]])
          : (() => {
              const hit = byCat[c].find(([w]) => vxImgURL(w));
              if (!hit) return '';
              const tw = hit[0];
              // 外层裁掉底部约 16%，去除源图右下角水印
              return `<span class="c-prev-wrap"><img class="c-prev-img" loading="lazy" alt="${escapeHtml(tw)}" src="${escapeHtml(vxImgURL(tw))}" onerror="(this.closest('.c-prev-wrap')||this).remove()"></span>`;
            })();
        const sample = c === '图标简笔'
          ? byCat[c].slice(0, 4).map(([w]) => escapeHtml(w)).join(' ')
          : byCat[c].slice(0, 4).map(([w, e]) => escapeHtml(e)).join(' ');
        return `
      <div class="cat-card" data-pcat="${escapeHtml(c)}">
        <div class="c-name">${PICT_ICONS[c] || '✨'} ${escapeHtml(c)}</div>
        ${preview ? `<div class="c-prev">${preview}</div>` : ''}
        <div class="c-count">${sample}</div>
        <span class="badge">${byCat[c].length} 词</span>
      </div>`;
      }).join('')}
    </div>`;
  view.querySelector('#back').onclick = back;
  // 预览缩略图加载失败：移除整块（含外层裁切容器），保持布局整洁
  view.querySelectorAll('.c-prev-img').forEach((img) => { img.addEventListener('error', () => { (img.closest('.c-prev-wrap') || img).remove(); }); });
  view.querySelectorAll('.cat-card[data-pcat]').forEach((card) => {
    card.addEventListener('click', () => renderPictGrid(view, ctx, APP, tax, card.dataset.pcat));
  });
  view.scrollTop = 0;
}

function renderPictGrid(view, ctx, APP, tax, cat, page) {
  if (typeof page !== 'number' || page < 0) page = 0;
  const m = wordMap(APP);
  const isIconCat = cat === '图标简笔';
  const isMeanCat = cat === '义符';
  const all = isIconCat
    ? Object.entries(tax.pictIcon || {}).filter(([w]) => m.has(w) && !tax.pict[w])
        .sort((a, b) => ((m.get(a[0]).difficulty || 9) - (m.get(b[0]).difficulty || 9)) || a[0].localeCompare(b[0]))
    : Object.entries(tax.pict || {}).filter(([w, [, c]]) => c === cat && m.has(w))
        .sort((a, b) => ((m.get(a[0]).difficulty || 9) - (m.get(b[0]).difficulty || 9)) || a[0].localeCompare(b[0]));
  const PAGE = 48;
  const totalPages = Math.max(1, Math.ceil(all.length / PAGE));
  if (page >= totalPages) page = totalPages - 1;
  const items = all.slice(page * PAGE, page * PAGE + PAGE);
  const shortMeaning = (w) => { const x = m.get(w); return ((x && x.meaning) || '').split(/[；;]/)[0]; };
  const imgHTML = (w, v) => {
    if (isIconCat) return iconSvg(v);                 // 图标简笔模块：保留 SVG 简笔（本身就是简笔画）
    const em = escapeHtml((v && v[0]) || '🔤');        // 表情图兜底
    // 精确助记图优先：vxiaozhi 每个单词的 AI 助记图像（按单词命名，对应精准），无图回退 emoji
    const url = vxImgURL(w);
    // 外层 .p-img-wrap 裁掉底部约 15%，去除源图右下角「小智晖的AI单词本」水印
    if (url) return `<span class="p-img-wrap"><img class="p-img" loading="lazy" alt="${escapeHtml(w)}" src="${escapeHtml(url)}" data-emoji="${em}"></span>`;
    // 无 vxiaozhi 图：回退 Unicode emoji（象形/义符类）
    return `<span class="p-e">${em}</span>`;
  };
  const pager = (pos) => `
    <div class="pager pager-${pos}">
      <button class="btn sm ghost" data-pg="prev" ${page <= 0 ? 'disabled' : ''}>‹ 上一页</button>
      <span class="pager-info">第 ${page + 1}/${totalPages} 页 · 共 ${all.length} 词</span>
      <button class="btn sm ghost" data-pg="next" ${page + 1 >= totalPages ? 'disabled' : ''}>下一页 ›</button>
    </div>`;
  view.innerHTML = `
    <div class="section-title">🧩象形记 · ${escapeHtml(cat)}（${all.length} 词）</div>
    <div class="card"><div class="between"><h2>${PICT_ICONS[cat] || '✨'} ${escapeHtml(cat)}</h2><button class="btn sm ghost" id="back">返回</button></div>
    <p class="hint" style="margin-top:4px">${isMeanCat ? '含义联想：用单词中文释义里的关键词配 emoji，建立图像关联（本地生成，不联网）。' : '点击任意词卡进入闪记；点「全部闪记」从该分类第一个词开始过词。单词优先显示 vxiaozhi AI 助记图（按词义精确生成），无图时回退 emoji。'}每页 ${PAGE} 词，可翻页浏览。</p></div>
    ${totalPages > 1 ? pager('top') : ''}
    <div class="pict-grid">
      ${items.map(([w, v]) => `
      <button class="pict-card" data-word="${escapeHtml(w)}">
        ${imgHTML(w, v)}
        <span class="p-w">${escapeHtml(w)}</span>
        <span class="p-m">${escapeHtml(shortMeaning(w).slice(0, 18))}</span>
      </button>`).join('')}
    </div>
    ${totalPages > 1 ? pager('bottom') : ''}
    <button class="btn block mt" id="allFlash">${IC.zapSm}全部闪记（${all.length} 词）</button>`;
  view.querySelector('#back').onclick = () => renderPictCats(view, ctx, APP, tax);
  const goPage = (p) => renderPictGrid(view, ctx, APP, tax, cat, p);
  view.querySelectorAll('[data-pg]').forEach((b) => b.addEventListener('click', () => {
    if (b.disabled) return;
    if (b.dataset.pg === 'prev') goPage(page - 1);
    else goPage(page + 1);
  }));
  view.querySelectorAll('.pict-card').forEach((b) => {
    b.addEventListener('click', () => {
      const w = m.get(b.dataset.word);
      if (w) openCategory(view, ctx, `象形记 · ${w.word}`, [w], () => renderPictGrid(view, ctx, APP, tax, cat, 0));
    });
  });
  // 真实语义照片加载失败 → 回退 emoji（表情图兜底）
  view.querySelectorAll('.p-img').forEach((img) => {
    img.addEventListener('error', function onErr() {
      const sp = document.createElement('span'); sp.className = 'p-e'; sp.textContent = img.dataset.emoji || '🔤';
      (img.closest('.p-img-wrap') || img).replaceWith(sp);
    });
  });
  view.querySelector('#allFlash').onclick = () => {
    const act = all.map(([w]) => m.get(w)).filter((w) => w && !isMastered(w.word) && ctx.matchDifficulty(w));
    if (!act.length) { ctx.toast('该分类在当前难度下暂无待练单词 🎉'); return; }
    openCategory(view, ctx, `象形记 · ${cat}`, act, () => renderPictGrid(view, ctx, APP, tax, cat, 0));
  };
  view.scrollTop = 0;
}

function openHSUnits(view, ctx, APP) {  const groups = hsUnitGroups(APP);
  const backToGrid = () => window.dispatchEvent(new CustomEvent('goto', { detail: 'category' }));
  view.innerHTML = `
    <div class="section-title">${IC.book}高中分单元记忆</div>
    <div class="card">
      <div class="between"><h2>按册 · 单元练习</h2><button class="btn sm ghost" id="back">返回分类</button></div>
      <p class="hint" style="margin-top:4px">点选某册下的单元，进入单词闪记与练习（已掌握的单词自动隐藏，遵循当前全局难度设置）。</p>
    </div>
    ${groups.map((bk) => `
      <div class="hs-book">
        <div class="hs-book-title">${IC.bookOpenSm}${escapeHtml(bk.units[0] ? bk.units[0].unit.replace(/U\d+$/, '').replace(/\s*Welcome\s*Unit$/i, '') : '') || '其他'}</div>
        <div class="cat-grid">
          ${bk.units.map((u) => {
            const all = u.words;
            const active = all.filter((w) => !isMastered(w.word) && ctx.matchDifficulty(w));
            const masteredCount = all.length - active.length;
            const badge = active.length ? `${active.length} 词待练` : '当前难度无待练';
            return `
            <div class="cat-card" data-unit="${escapeHtml(u.unit)}">
              <div class="c-name">${escapeHtml(u.unit)}</div>
              <div class="c-count">${all.length} 词${masteredCount ? ` · 已掌握 ${masteredCount}` : ''}</div>
              <span class="badge">${badge}</span>
            </div>`;
          }).join('')}
        </div>
      </div>
    `).join('')}
  `;
  view.querySelector('#back').onclick = backToGrid;
  view.querySelectorAll('.cat-card[data-unit]').forEach((card) => {
    card.addEventListener('click', () => {
      const unit = card.dataset.unit;
      const all = (APP.library.words || []).filter((w) => w.pep && w.pep.band === '高中' && w.pep.unit === unit);
      const active = all.filter((w) => !isMastered(w.word) && ctx.matchDifficulty(w));
      if (!active.length) { ctx.toast('该单元在当前难度下暂无待练单词 🎉'); return; }
      openCategory(view, ctx, unit, active, () => openHSUnits(view, ctx, APP));
    });
  });
}

function openCategory(view, ctx, title, words, onBack) {
  let mode = 'flash'; // flash | quiz
  let idx = 0;

  function modeBar() {
    return `
      <div class="reading-mode-bar">
        <button class="mode-btn ${mode === 'flash' ? 'on' : ''}" data-mode="flash">${IC.zapSm}单词闪记</button>
        <button class="mode-btn ${mode === 'quiz' ? 'on' : ''}" data-mode="quiz">${IC.pencilSm}开始练习</button>
      </div>`;
  }
  function bindModeBar() {
    view.querySelectorAll('.mode-btn').forEach((b) => {
      b.addEventListener('click', () => {
        const m = b.dataset.mode;
        if (m === 'quiz') { runStudy(view, ctx, words, title); return; }
        mode = m; render();
      });
    });
  }

  function render() {
    if (mode === 'flash') return renderFlash();
    // quiz 交由 runStudy 接管视图
    runStudy(view, ctx, words, title);
  }

  function renderFlash() {
    const w = words[idx];
    view.innerHTML = `
      <div class="card">
        <div class="between"><h2><svg class="vico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3.5" y="3.5" width="7" height="7" rx="1.6"/><rect x="13.5" y="3.5" width="7" height="7" rx="1.6"/><rect x="3.5" y="13.5" width="7" height="7" rx="1.6"/><rect x="13.5" y="13.5" width="7" height="7" rx="1.6"/></svg>${escapeHtml(title)} · 单词闪记</h2><button class="btn sm ghost" id="back">返回</button></div>
        <div class="pill" style="margin-top:8px">${idx + 1} / ${words.length}</div>
        ${modeBar()}
      </div>
      <div class="flash-wrap">
        <button class="flash-arrow left" id="arrowPrev" aria-label="上一个">‹</button>
        <div id="flashCard"></div>
        <button class="flash-arrow right" id="arrowNext" aria-label="下一个">›</button>
      </div>
      <div class="row mt">
        <button class="btn gray block" id="prev">上一张</button>
        <button class="btn ghost block" id="next">下一张</button>
      </div>
      <button class="btn block mt" id="toQuiz">${IC.checkSm}开始练习</button>
    `;
    const wrap = view.querySelector('#flashCard');
    wrap.innerHTML = wordCardHTML(w, { showNote: true });
    bindWordCardEvents(wrap, ctx);
    // 自动播放英式发音
    ctx.playUK(w.word);
    bindModeBar();
    const goPrev = () => { idx = (idx - 1 + words.length) % words.length; renderFlash(); };
    const goNext = () => { idx = (idx + 1) % words.length; renderFlash(); };
    view.querySelector('#prev').onclick = goPrev;
    view.querySelector('#next').onclick = goNext;
    const ap = view.querySelector('#arrowPrev'); if (ap) ap.onclick = goPrev;
    const an = view.querySelector('#arrowNext'); if (an) an.onclick = goNext;
    view.querySelector('#toQuiz').onclick = () => runStudy(view, ctx, words, title);
    view.querySelector('#back').onclick = onBack || (() => window.dispatchEvent(new CustomEvent('goto', { detail: 'category' })));
    // 切换卡片后回到顶部（而非停留在当前滚动位置）
    view.scrollTop = 0;
  }

  render();
}


// 快筛听写模块
// 模式：难度听（按 difficulty 本级/本级以下）/ 同步听（按人教版PEP 年级+单元）
// 顺序 / 随机；仅英音；自拼英文 + 中文10选1。
// 难度听：英文+中文一次全对 → 掌握；同步听：连续对 3 次 → 掌握，错则连击清零。

const DICT_DIFF_LABELS = { 1: '小学', 2: '初中', 3: '高中', 4: '四级', 5: '六级', 6: '考研', 7: 'GRE' };
const dictNormalizeInput = (s) => (s || '').toLowerCase().replace(/[\s'’]/g, '').trim();
// 人教版高中册顺序（用于单元排序）
const BOOK_ORDER = { 必修一: 0, 必修二: 1, 必修三: 2, 选必一: 3, 选必二: 4, 选必三: 5, 选必四: 6 };
// 单元排序键：Welcome Unit 置顶于所属册（单元号用 -1），其余按「册序 + 单元号」
function unitSortKey(u) {
  if (!u) return [99, 99];
  // 任一册的 Welcome Unit 都置于该册最前（如「必修一 Welcome Unit」「选必二 Welcome Unit」）
  const wm = /^(.+?)\s*Welcome\s*Unit$/i.exec(u);
  if (wm) return [BOOK_ORDER[wm[1]] != null ? BOOK_ORDER[wm[1]] : 99, -1];
  const m = /^([^U]+)U(\d+)$/.exec(u);
  if (!m) return [99, 99];
  return [BOOK_ORDER[m[1]] != null ? BOOK_ORDER[m[1]] : 99, Number(m[2])];
}

// 当天已听写单词（小写数组）：用于「每个单词每天只听写一轮」的防重复机制。
// 跨天自动重置；旧进度缺字段时回退空数组，绝不抛错。
function todayStr() { const d = new Date(); return d.getFullYear() + '-' + (d.getMonth() + 1) + '-' + d.getDate(); }
function todayDictated(APP) {
  const p = APP.progress;
  if (!p.dictatedLog || p.dictatedLog.date !== todayStr()) p.dictatedLog = { date: todayStr(), words: [] };
  if (!Array.isArray(p.dictatedLog.words)) p.dictatedLog.words = [];
  return p.dictatedLog.words;
}

const __mod_dictation = {
  render({ view, APP, ctx }) {
    // 注册「离开本模块」停播钩子：app.js 的 goto 在切换页面前调用，停止播报计时与自动跳转
    window.__hvDictStop = () => {
      stopAudio();
      if (autoTimer) { clearTimeout(autoTimer); autoTimer = null; }
    };
    const st = {
      mode: 'diff',                                   // diff | sync
      diffLevel: (APP.settings && APP.settings.difficulty) || 'all',   // 1..7 | 'all'
      diffScope: 'le',                                // 'eq' 仅本级 | 'le' 本级及以下
      syncBand: '小学',                               // 小学 | 初中 | 高中
      syncUnit: 'all',                                // 'all' | '必修一U1' ...
      order: 'seq',                                   // 'seq' 顺序 | 'rand' 随机
      cnt: 20, plays: 3, interval: 10,
      all: false,                                     // true=听写全部（本范围未听写/未掌握单词）
    };
    let words = [], idx = 0, masteredCnt = 0, wrongCnt = 0;
    const wrongWords = [];
    let playTimer = null;
    let autoTimer = null; // 全对后自动进入下一题的定时器
    let streakMap = {}; // 同步听：每词连续正确次数（顺序推进，不锁定同一词）
    let presented = 0;  // 已呈现单词计数
    let streak = 0;     // 当前单词的连击数（必须先声明：ESM 为严格模式，未声明赋值会抛 ReferenceError）

    function stopAudio() { if (playTimer) { clearTimeout(playTimer); playTimer = null; } }

    // 按 difficulty 过滤（独立于全局设置）；GRE 桶去重后的「有效难度」优先
    function matchDiff(w, lv, scope) {
      if (lv === 'all') return true;
      const d = (ctx && ctx.difficultyOf) ? ctx.difficultyOf(w) : w.difficulty;
      if (d == null) return false;
      const n = Number(lv);
      return scope === 'eq' ? d === n : d <= n;
    }

    // 取某年级下所有单元（去重，按册+单元排序）
    function unitsOf(band) {
      const set = new Set();
      for (const w of (APP.library.words || [])) {
        const p = w.pep;
        if (p && p.band === band && p.unit) set.add(p.unit);
      }
      const key = (u) => unitSortKey(u);
      return [...set].sort((a, b) => { const x = key(a), y = key(b); return x[0] - y[0] || x[1] - y[1]; });
    }

    // includeDictated=true 时不排除「当天已听写」单词（用于判断范围内是否还有单词可听写）
    function candidates(includeDictated) {
      let pool = (APP.library.words || []).filter((w) =>
        w.word && w.meaning && !APP.progress.mastered[w.word.toLowerCase()]);
      // 防重复：排除当天已经听写过的单词（每个单词每天只听写一轮）
      if (!includeDictated) {
        const done = todayDictated(APP);
        if (done.length) pool = pool.filter((w) => !done.includes(w.word.toLowerCase()));
      }
      if (st.mode === 'diff') {
        pool = pool.filter((w) => matchDiff(w, st.diffLevel, st.diffScope));
      } else {
        pool = pool.filter((w) => {
          const p = w.pep;
          if (!p || p.band !== st.syncBand) return false;
          if (st.syncUnit !== 'all' && p.unit !== st.syncUnit) return false;
          return true;
        });
        if (st.order === 'seq') {
          const key = (w) => {
            const p = w.pep || {};
            const sk = unitSortKey(p.unit || '');
            return [sk[0], sk[1], w.word];
          };
          pool = pool.slice().sort((a, b) => { const x = key(a), y = key(b); return x[0] - y[0] || x[1] - y[1] || (x[2] < y[2] ? -1 : 1); });
          return pool;
        }
      }
      return st.order === 'rand' ? shuffle(pool) : pool;
    }

    // 逐词标记「今天已听写」：仅在该单词真正被呈现（听到/作答）时记录。
    // 关键：不再于开轮时把整批单词一次性写入——否则中途退出时，未听到的词会被误吞，
    // 导致「当天没听过的单词」在听写模块里不再显示。返回 true 表示本次新增。
    function markDictated(w) {
      const lw = String(w && w.word ? w.word : w).toLowerCase();
      if (!lw) return false;
      const done = todayDictated(APP);
      if (done.includes(lw)) return false;
      done.push(lw);
      return true;
    }

    // 开始/再来一轮：取「当天未听写过」的候选词；「听写全部」时取本范围全部，否则按单词量截取。
    // 已在候选池中排除当天听写过的词；本轮单词在真正呈现时才逐词记为「今天已听写」。
    function beginRound() {
      stopAudio();
      const allFull = candidates(true);   // 包含当天已听写的（用于判断范围内是否还有词）
      const all = candidates(false);       // 排除当天已听写的
      if (!allFull.length) {
        ctx.toast(st.mode === 'sync' ? '该年级/单元下没有可听写的单词' : '当前难度下没有可听写的单词');
        return;
      }
      if (!all.length) { renderAllDone(); return; }
      st.cnt = Math.max(5, Math.min(200, st.cnt));
      words = st.all ? all : all.slice(0, Math.max(1, st.cnt));
      masteredCnt = 0; wrongCnt = 0; wrongWords.length = 0; streakMap = {};
      idx = 0; presented = 1;
      presentWord(words[idx], 0);
    }

    function renderConfig() {
      stopAudio();
      const levels = [['all', '全部（不限难度）']].concat([1, 2, 3, 4, 5, 6, 7].map((l) => [l, DICT_DIFF_LABELS[l]]));
      const diffOpts = levels.map(([lv, label]) =>
        `<label class="diff-opt"><input type="radio" name="df" value="${lv}" ${String(st.diffLevel) === String(lv) ? 'checked' : ''}> ${label}</label>`).join('');
      const unitOpts = ['<option value="all">全部单元</option>']
        .concat(unitsOf(st.syncBand).map((u) => `<option value="${escapeHtml(u)}" ${st.syncUnit === u ? 'selected' : ''}>${escapeHtml(u)}</option>`)).join('');
      const bandHint = st.syncBand !== '高中' && unitsOf(st.syncBand).length === 0
        ? '<p class="hint" style="margin-top:4px">该年级单元词表待导入，将按整个年级听写。</p>' : '';
      // 今日进度（逐词统计）：本范围未掌握总数 - 今天还没听写的 = 今天已听写
      const inScope = candidates(true).length;
      const remainCnt = candidates(false).length;
      const doneCnt = Math.max(0, inScope - remainCnt);

      view.innerHTML = `
        <div class="section-title">${IC.zap}快筛听写</div>
        <div class="card">
          <h2 style="margin-bottom:6px">听写设置</h2>
          <p class="hint">仅播放英式发音，需自行拼写英文，并从 10 个选项中选出中文释义。</p>

          <div class="field"><label>听写模式</label>
            <div class="seg">
              <button class="seg-btn ${st.mode === 'diff' ? 'on' : ''}" data-mode="diff">难度听</button>
              <button class="seg-btn ${st.mode === 'sync' ? 'on' : ''}" data-mode="sync">同步听</button>
            </div>
          </div>

          <div id="diffBox" style="${st.mode === 'diff' ? '' : 'display:none'}">
            <div class="field"><label>难度范围</label><div class="diff-opts">${diffOpts}</div></div>
            <div class="field" id="scopeBox" style="${st.diffLevel === 'all' ? 'display:none' : ''}"><label>范围方式</label>
              <div class="seg">
                <button class="seg-btn ${st.diffScope === 'eq' ? 'on' : ''}" data-scope="eq">仅本级</button>
                <button class="seg-btn ${st.diffScope === 'le' ? 'on' : ''}" data-scope="le">本级及以下</button>
              </div>
            </div>
          </div>

          <div id="syncBox" style="${st.mode === 'sync' ? '' : 'display:none'}">
            <div class="field"><label>年级（人教版PEP）</label>
              <div class="seg">
                <button class="seg-btn ${st.syncBand === '小学' ? 'on' : ''}" data-band="小学">小学</button>
                <button class="seg-btn ${st.syncBand === '初中' ? 'on' : ''}" data-band="初中">初中</button>
                <button class="seg-btn ${st.syncBand === '高中' ? 'on' : ''}" data-band="高中">高中</button>
              </div>
            </div>
            <div class="field"><label>单元</label>
              <select id="syncUnit" class="typing">${unitOpts}</select>
            </div>
            ${bandHint}
          </div>

          <div class="field"><label>听写顺序</label>
            <div class="seg">
              <button class="seg-btn ${st.order === 'seq' ? 'on' : ''}" data-order="seq">顺序</button>
              <button class="seg-btn ${st.order === 'rand' ? 'on' : ''}" data-order="rand">随机</button>
            </div>
          </div>

          <div class="field"><label class="chk"><input type="checkbox" id="allChk" ${st.all ? 'checked' : ''}> 听写全部（本范围所有未听写、未掌握的单词）</label></div>
          <div class="field"><label>听写单词量</label><input type="number" class="typing" id="cnt" value="${st.cnt}" min="5" max="200" ${st.all ? 'disabled' : ''}></div>
          <div class="field"><label>每个单词播报次数</label><input type="number" class="typing" id="plays" value="${st.plays}" min="1" max="6"></div>
          <div class="field"><label>播报间隔（秒）</label><input type="number" class="typing" id="iv" value="${st.interval}" min="1" max="10"></div>
          <p class="hint" style="margin-top:-2px">今日本范围：已听写 <b>${doneCnt}</b> 词 · 剩余可听写 <b>${remainCnt}</b> 词。限制按<b>单词</b>逐词记录（与模块执行次数无关）——听过的词今天不再出现，没听过的词正常出现。</p>

          <button class="btn block mt" id="start">${IC.playSm}开始听写</button>
        </div>`;

      // 模式切换
      view.querySelectorAll('[data-mode]').forEach((b) => b.onclick = () => { st.mode = b.dataset.mode; renderConfig(); });
      view.querySelectorAll('[data-scope]').forEach((b) => b.onclick = () => { st.diffScope = b.dataset.scope; renderConfig(); });
      view.querySelectorAll('[data-band]').forEach((b) => b.onclick = () => { st.syncBand = b.dataset.band; st.syncUnit = 'all'; renderConfig(); });
      view.querySelectorAll('[data-order]').forEach((b) => b.onclick = () => { st.order = b.dataset.order; renderConfig(); });
      view.querySelectorAll('input[name="df"]').forEach((r) => r.onchange = () => {
        st.diffLevel = r.value;
        const sb = view.querySelector('#scopeBox');
        if (sb) sb.style.display = st.diffLevel === 'all' ? 'none' : '';
      });
      const su = view.querySelector('#syncUnit');
      if (su) su.onchange = () => { st.syncUnit = su.value; };
      const allChk = view.querySelector('#allChk');
      if (allChk) allChk.onchange = () => { st.all = allChk.checked; renderConfig(); };
      const bindNum = (id, key) => { const el = view.querySelector('#' + id); if (el) el.oninput = () => { st[key] = parseInt(el.value, 10) || st[key]; }; };
      bindNum('cnt', 'cnt'); bindNum('plays', 'plays'); bindNum('iv', 'interval');

      view.querySelector('#start').onclick = () => beginRound();
    }

    function playSeries(word, n, interval) {
      stopAudio();
      let i = 0;
      const step = () => {
        if (i >= n) { playTimer = null; return; }
        ctx.playUK(word);
        i++;
        if (i < n) playTimer = setTimeout(step, interval * 1000);
      };
      step();
    }

    function presentWord(w, curStreak) {
      streak = curStreak;
      // 逐词精确记录：该单词此刻真正呈现（听到/作答）后才算「今天已听写」
      if (markDictated(w)) ctx.saveProgress();
      // 中文选项用「常用译文」（取首义项），避免一长串义项；并去重
      const pool = words.filter((x) => x.word !== w.word && x.meaning);
      const options = buildEn2ZhOptions(w.meaning, pool, 10);
      const answerZh = commonMeaning(w.meaning) || w.meaning;
      let chosenZh = null;
      const isSync = st.mode === 'sync';
      const remaining = words.filter((x) => !APP.progress.mastered[x.word.toLowerCase()]).length;
      const progLabel = isSync
        ? `已掌握 <b>${masteredCnt}</b> · 待掌握 <b>${remaining}</b>`
        : `单词 ${idx + 1} / ${words.length}`;
      const streakPill = isSync
        ? `<span class="stat-pill ${streak >= 2 ? 'ok' : 'warn'}">连击 ${streak}/3</span>` : '';
      view.innerHTML = `
        <div class="card">
          <div class="between"><h2>${IC.zap}听写</h2><span class="pill">${progLabel}</span></div>
          <div class="dictate-status">
            <span class="stat-pill ok">掌握 <b>${masteredCnt}</b></span>
            <span class="stat-pill warn">未掌握 <b>${wrongCnt}</b></span>
            ${streakPill}
          </div>
          <div class="dictate-audio">
            <button class="audio-btn big" id="replay" title="重播英音">${IC.volumeSm}重播</button>
            <span class="hint">${isSync ? '同步听：连续拼对 3 次才判定掌握，错一次连击清零。' : '正在播放英式发音…'}</span>
          </div>
          <div class="field"><label>拼写英文</label><input type="text" class="typing" id="en" placeholder="输入听到的单词" autocomplete="off" autocorrect="off" spellcheck="false"></div>
          <div class="hint">选择中文释义（10 选 1）：</div>
          <div id="opts" class="opts-grid">${options.map((o, i) => `<button class="opt" data-i="${i}">${escapeHtml(o)}</button>`).join('')}</div>
          <div id="explain" class="example mt" style="display:none"></div>
        </div>
        <button class="btn block mt" id="submit">提交</button>
        ${isSync ? '<button class="btn gray block mt" id="skip">跳过本题</button>' : ''}`;
      view.querySelector('#replay').onclick = () => playSeries(w.word, st.plays, st.interval);
      const input = view.querySelector('#en');
      input.focus();
      playSeries(w.word, st.plays, st.interval);
      const opts = view.querySelectorAll('.opt');
      opts.forEach((b) => b.addEventListener('click', () => {
        if (chosenZh !== null) return;
        chosenZh = options[+b.dataset.i];
        opts.forEach((x) => { x.disabled = true; if (options[+x.dataset.i] === answerZh) x.classList.add('correct'); else if (x === b) x.classList.add('wrong'); });
        check(w);
      }));
      function check(wd) {
        const enOk = dictNormalizeInput(input.value) === dictNormalizeInput(wd.word);
        const zhOk = chosenZh === answerZh;
        const exp = view.querySelector('#explain');
        exp.style.display = 'block';
        const submit = view.querySelector('#submit');
        // 全对：展示反馈后自动进入下一题（点击按钮/回车可立即跳过等待）；做错：手动点「下一题 →」
        const scheduleAuto = () => {
          if (autoTimer) clearTimeout(autoTimer);
          autoTimer = setTimeout(() => { autoTimer = null; advance(); }, 1200);
        };
      if (isSync) {
        if (enOk && zhOk) {
          const s = (streakMap[wd.word] || 0) + 1;
          streakMap[wd.word] = s;
          if (s >= 3) {
            masteredCnt++;
            ctx.markMastered(wd.word);
            exp.innerHTML = IC.checkSm + '连续 3 次正确，已掌握 ' + escapeHtml(wd.word) + '！+10星';
          } else {
            exp.innerHTML = IC.checkSm + '正确（连续 ' + s + '/3），即将进入下一个单词…';
          }
          submit.textContent = (masteredCnt >= words.length) ? '完成' : '下一题 →';
          submit.onclick = advance;
          scheduleAuto();
        } else {
          streakMap[wd.word] = 0;
          wrongCnt++;
          if (!wrongWords.includes(wd.word)) wrongWords.push(wd.word);
          ctx.recordWrongAnswer(wd.word, false);
          const tips = [];
          if (!enOk) tips.push('英文应为 ' + escapeHtml(wd.word));
          if (!zhOk) tips.push('正确中文：' + escapeHtml(answerZh));
          exp.innerHTML = IC.xSm + '连击清零。' + tips.join('；');
          submit.textContent = '下一题 →';
          submit.onclick = advance;
        }
      } else {
        if (enOk && zhOk) {
          masteredCnt++;
          ctx.markMastered(wd.word);
          exp.innerHTML = IC.checkSm + '英文与中文都答对，已掌握 ' + escapeHtml(wd.word) + '！+10星';
          scheduleAuto();
        } else {
          wrongCnt++;
          if (!wrongWords.includes(wd.word)) wrongWords.push(wd.word);
          ctx.recordWrongAnswer(wd.word, false);
          const tips = [];
          if (!enOk) tips.push('英文应为 ' + escapeHtml(wd.word));
          if (!zhOk) tips.push('正确中文：' + escapeHtml(answerZh));
          exp.innerHTML = IC.xSm + tips.join('；');
        }
        submit.textContent = idx < words.length - 1 ? '下一题 →' : '完成';
        submit.onclick = advance;
      }
      }
      if (isSync) {
        const skip = view.querySelector('#skip');
        if (skip) skip.onclick = () => { streakMap[w.word] = 0; advance(); };
      }
      input.addEventListener('keydown', (e) => { if (e.key === 'Enter' && chosenZh !== null) (view.querySelector('#submit').onclick || function () {}).call(); });
      view.querySelector('#submit').onclick = () => { ctx.toast('请先选择中文释义'); };
    }

    // 只向前扫描：本轮每个候选词各呈现一次，到末尾即完成，绝不回绕（回绕会导致答错的词永远不被掌握而无限循环）。
    function nextUnmastered(from) {
      if (!words.length) return -1;
      for (let i = from; i < words.length; i++) {
        if (!APP.progress.mastered[words[i].word.toLowerCase()]) return i;
      }
      return -1;
    }
    function advance() {
      if (autoTimer) { clearTimeout(autoTimer); autoTimer = null; } // 手动/定时二选一，防止连跳两题
      const ni = nextUnmastered(idx + 1);
      if (ni < 0) { renderDone(); return; }
      idx = ni; presented++;
      presentWord(words[idx], streakMap[words[idx].word] || 0);
    }

    function renderDone() {
      stopAudio();
      if (autoTimer) { clearTimeout(autoTimer); autoTimer = null; }
      ctx.completeSession(words, new Set(wrongWords));
      const modeHint = st.mode === 'sync'
        ? '同步听：需连续拼对 3 次才判定掌握，错一次连击清零。'
        : '难度听：英文与中文一次全对即判定掌握。';
      const wbCount = (APP.progress.wrongBook || []).filter((w) =>
        !(APP.progress.mastered && APP.progress.mastered[String(w).toLowerCase()])).length;
      view.innerHTML = `
        <div class="card" style="text-align:center">
          <h2>${IC.checkSm}听写完成！</h2>
          <div class="stat-grid">
            <div class="stat"><div class="num">${words.length}</div><div class="lab">听写单词</div></div>
            <div class="stat"><div class="num ok">${masteredCnt}</div><div class="lab">已掌握</div></div>
            <div class="stat"><div class="num warn">${wrongCnt}</div><div class="lab">未掌握</div></div>
          </div>
          <p class="hint mt">${modeHint}</p>
          <p class="hint">本轮<b>实际听过</b>的单词已逐词记录，今天不再出现；未听到的单词下次仍会正常出现。</p>
          ${wrongWords.length ? `<p class="hint">未掌握的 <b>${wrongWords.length}</b> 个单词已自动进入「错词本」，建议去错词本复习。</p>` : ''}
          <button class="btn block mt" id="again">${IC.rotateSm}再来一轮（听写未听写的单词）</button>
          ${wrongWords.length ? `<button class="btn warn block mt" id="wb">${IC.bookXSm}去错词本复习错词（${wrongWords.length}）</button>` : ''}
          <button class="btn gray block mt" id="back">返回设置</button>
        </div>`;
      view.querySelector('#again').onclick = () => beginRound();
      view.querySelector('#back').onclick = () => renderConfig();
      const wbBtn = view.querySelector('#wb');
      if (wbBtn) wbBtn.onclick = () => window.dispatchEvent(new CustomEvent('goto', { detail: 'wrongbook' }));
    }

    // 当天范围内所有单词都已听写过：不再重复，引导去错词本复习
    function renderAllDone() {
      stopAudio();
      if (autoTimer) { clearTimeout(autoTimer); autoTimer = null; }
      const wbCount = (APP.progress.wrongBook || []).filter((w) =>
        !(APP.progress.mastered && APP.progress.mastered[String(w).toLowerCase()])).length;
      view.innerHTML = `
        <div class="card" style="text-align:center">
          <h2>${IC.checkSm}今天的单词都听写过了</h2>
          <p class="hint mt">快筛听写用于快速筛选你已掌握的单词，<b>每个单词每天只听写一轮</b>。当前筛选范围内的单词今天都已听写过，不再重复。</p>
          ${wbCount ? `<p class="hint">还有 <b>${wbCount}</b> 个错词在「错词本」里，建议去专项复习巩固。</p>` : '<p class="hint">错词本已清空，非常棒！</p>'}
          <button class="btn block mt" id="wb">${IC.bookXSm}去错词本复习</button>
          <button class="btn gray block mt" id="back">返回设置</button>
        </div>`;
      view.querySelector('#wb').onclick = () => window.dispatchEvent(new CustomEvent('goto', { detail: 'wrongbook' }));
      view.querySelector('#back').onclick = () => renderConfig();
    }

    renderConfig();
  },
};



